function groups() { return readTable('Groups'); }
function defaultGroupId() { return String(groups()[0].Id); }
function groupOf(kid) { return String(kid.Group || '').trim() || defaultGroupId(); }
function findGroup(id) { return groups().filter(function (g) { return String(g.Id) === String(id); })[0]; }
function kidsIn(groupId) { return readTable('Girls').filter(function (k) { return groupOf(k) === groupId; }); }

function groupLink(id) {
  var base = publicUrl();
  // The main family's link carries its id too: a phone that remembers another family is switched back by it.
  return base + (base.indexOf('?') < 0 ? '?' : '&') + 'g=' + encodeURIComponent(id);
}

// Rewards rows with a Group apply to that group only; rows without one apply to every group
// that has no rewards of its own.
function rewardsFor(groupId) {
  var rows = readTable('Rewards');
  var own = rows.filter(function (r) { return String(r.Group || '').trim() === groupId; });
  var list = own.length ? own : rows.filter(function (r) { return !String(r.Group || '').trim(); });
  return list.map(function (r) { return { points: Number(r.Points), reward: r.Reward }; })
    .sort(function (a, b) { return a.points - b.points; });
}

// ---------- Client API ----------

function apiPublic(groupId) {
  ensureSetup();
  var g = groupId ? findGroup(groupId) : groups()[0];
  if (!g) throw new Error('This link is not valid — ask your parent for the right one.');
  return {
    group: { id: String(g.Id), name: g.Name },
    girls: kidsIn(String(g.Id)).map(function (k) {
      var pet = petInfo(k);
      return { name: k.Name, color: k.Color, age: k.Age, pet: pet ? { id: pet.id, stage: pet.stage } : null };
    }),
    word: wordOfDay(today()),
    today: today()
  };
}

// Called when a kid taps her name, while she types her PIN: fills the cache.
function apiWarm() {
  ensureSetup();
  ['Girls', 'Assignments', 'Log', 'Rewards', 'Groups', 'Games', 'Review', 'Gates', 'Duels', 'Duos', 'Bonus', 'Shop', 'Wardrobe', 'Words'].forEach(readTable);
  return true;
}

function apiDashboard(name, pin) {
  var t = Date.now(), lap = function (k) { var n = Date.now(); PERF_PARTS[k] = n - t; t = n; };
  PERF_PARTS = {};
  var kid = auth(name, pin);
  lap('auth');
  auditOpen('kid', kid.Name, groupOf(kid));
  lap('open');
  var dash = buildDashboard(kid);
  lap('build');
  // Play together card (Duels.js); only here, so parent views and other calls stay fast.
  if (!dash.levelTest && !dash.nest) dash.duels = duelHome(kid);
  lap('duels');
  return dash;
}

function apiSubmit(name, pin, date, correct, total, levelResult) {
  var kid = auth(name, pin);
  if (isNest(kid)) throw new Error('Play today in the app');
  var t = today();
  var pending = pendingLevelTest(kid);
  if (pending) {
    // A new kid's level test can be done any day; it counts as done today.
    if (date !== pending.date) throw new Error('Take the level test first.');
    if (!levelResult || LEVELS.indexOf(levelResult) < 0) throw new Error('Choose your level');
    // Exercises handed out before the level test was required (nothing logged, so nothing is lost).
    dropAssignmentsExcept(kid.Name, date);
    if (date !== t) { moveAssignment(kid.Name, date, t); date = t; }
  } else if (weekDates(t).indexOf(date) < 0 || date > t || date < kidStart(kid)) {
    throw new Error('You can only log tasks from this week.');
  }
  var a = ensureAssignments(kid, [date])[date];
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    var done = readTableUncached('Log').filter(function (l) { return l.Girl === kid.Name && l.Date === date; });
    if (done.length) throw new Error('This task is already marked as done.');

    correct = Number(correct) || 0;
    total = Number(total) || 0;
    var pct = total > 0 ? Math.round(Math.min(correct, total) / total * 100) : '';
    var onTime = date === t;
    var points;
    if (a.section === 'level') {
      points = 15 + (onTime ? 3 : 0);
      if (levelResult && LEVELS.indexOf(levelResult) >= 0) setGirlField(kid.Name, 'Level', levelResult);
    } else {
      if (total <= 0) throw new Error('Please enter your score.');
      points = 10 + (pct >= 80 ? 5 : 0) + (onTime ? 3 : 0);
    }
    var entry = {
      Timestamp: new Date(), Girl: kid.Name, Date: date, DoneOn: t, Section: a.section,
      Level: a.section === 'level' ? (levelResult || '') : a.level, Title: a.title, URL: a.url,
      Correct: a.section === 'level' ? '' : correct, Total: a.section === 'level' ? '' : total,
      Percent: pct, Points: points
    };
    appendRow('Log', entry);
  } finally {
    lock.releaseLock();
  }
  try { notifyCompletion(kid, entry); } catch (e) { console.error(e); }
  try { duoAfterPractice(kid.Name); } catch (e) { console.error(e); }
  var dash = buildDashboard(findGirl(kid.Name));
  dash.justEarned = dash.week.filter(function (d) { return d.date === date; })[0].points;
  return dash;
}

// ---------- Mini-games & pets ----------

// One finished round. The score is measured by the game itself, so nothing is typed by hand.
// missed / right: ids of the items answered wrong / right, for the spaced review. second: items answered right on
// the second try (the Second Chance upgrade: half XP; they still count as missed for the review). game 'mine' = a
// round of her saved words (the Word Saver).
function apiGameResult(name, pin, game, level, correct, total, missed, right, second) {
  var kid = auth(name, pin);
  // 'review': a round of mission questions she missed (Missions.js), played like a game.
  if (GAMES.indexOf(game) < 0 && game !== 'mine' && game !== 'review') throw new Error('Unknown game');
  if (pendingLevelTest(kid)) throw new Error('Take the level test first.');
  correct = Math.round(Number(correct));
  total = Math.round(Number(total));
  if (!(total >= 1 && total <= 10 && correct >= 0 && correct <= total)) throw new Error('Invalid score');
  if (LEVELS.indexOf(level) < 0) level = kid.Level;
  missed = cleanIds(missed);
  right = cleanIds(right);
  second = Math.round(Number(second)) || 0;
  if (second < 0 || second > total - correct || !ownedItems(kid.Name)['second-chance']) second = 0;
  var t = today(), xp;
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    var used = readTableUncached('Games').filter(function (g) { return g.Girl === kid.Name && g.Date === t; })
      .reduce(function (a, g) { return a + (Number(g.XP) || 0); }, 0);
    xp = correct * GAME_XP.right + second * GAME_XP.right / 2 + (correct === total && total >= 5 ? GAME_XP.perfect : 0);
    xp = Math.max(0, Math.min(xp, GAME_XP.dayCap - used));
    appendRow('Games', { Timestamp: new Date(), Girl: kid.Name, Date: t, Game: game, Level: level,
      Correct: correct, Total: total, XP: xp, Missed: missed.join(' ') });
    updateReview(kid.Name, missed, right, t);
  } finally {
    lock.releaseLock();
  }
  try { duoAfterPractice(kid.Name); } catch (e) { console.error(e); }
  var dash = buildDashboard(findGirl(kid.Name));
  dash.gameXp = xp;
  return dash;
}

function apiSetPet(name, pin, petId, petName) {
  var kid = auth(name, pin);
  if (PETS.indexOf(petId) < 0) throw new Error('Choose a pet');
  petName = String(petName || '').replace(/[<>"]/g, '').replace(/\s+/g, ' ').trim().slice(0, 16);
  if (!petName) throw new Error('Give your pet a name');
  var fields = { Pet: petId, PetName: petName };
  if (!kid.PetSince) fields.PetSince = today();
  setGirlFields(kid.Name, fields);
  return buildDashboard(findGirl(kid.Name));
}

function cleanIds(list, max) {
  return (Array.isArray(list) ? list : []).map(String).filter(function (s) { return /^[A-Za-z0-9:_-]{1,40}$/.test(s); }).slice(0, max || 10);
}

// Pet growth: game and gate XP plus task points since adoption (tasks done before adopting don't count).
function petInfo(kid) {
  if (PETS.indexOf(kid.Pet) < 0) return null;
  var since = String(kid.PetSince || '');
  var xp = 0;
  readTable('Log').forEach(function (l) { if (l.Girl === kid.Name && String(l.DoneOn) >= since) xp += Number(l.Points) || 0; });
  readTable('Games').forEach(function (g) { if (g.Girl === kid.Name) xp += Number(g.XP) || 0; });
  readTable('Gates').forEach(function (g) { if (g.Girl === kid.Name) xp += Number(g.XP) || 0; });
  readTable('Bonus').forEach(function (b) { if (b.Girl === kid.Name) xp += Number(b.XP) || 0; });
  readTable('Chats').forEach(function (r) { if (r.Girl === kid.Name) xp += Number(r.XP) || 0; });
  var stage = 1;
  PET_STAGES.forEach(function (min, i) { if (xp >= min) stage = i + 1; });
  var w = wardrobeOf(kid.Name);
  return { id: kid.Pet, name: kid.PetName || '', xp: xp, stage: stage, from: PET_STAGES[stage - 1], to: PET_STAGES[stage] || null, since: since,
    wear: w.wear, move: w.move, shine: wornShine(kid, w.wear) };
}

function gameStats(kid, t, saver) {
  var rows = readTable('Games').filter(function (g) { return g.Girl === kid.Name; });
  var todayRows = rows.filter(function (g) { return g.Date === t; });
  var week = weekDates(t);
  var weekRows = rows.filter(function (g) { return week.indexOf(g.Date) >= 0; });
  var pct = function (list) {
    var c = 0, n = 0;
    list.forEach(function (g) { c += Number(g.Correct) || 0; n += Number(g.Total) || 0; });
    return n ? Math.round(c / n * 100) : null;
  };
  // Rows with questions; a duel's win bonus is a row without any.
  var played = function (g) { return Number(g.Total) > 0; };
  var recent = {};
  GAMES.forEach(function (name) {
    recent[name] = rows.filter(function (g) { return g.Game === name; }).slice(-3).map(function (g) {
      return Number(g.Total) ? Math.round(Number(g.Correct) / Number(g.Total) * 100) : 0;
    });
  });
  return {
    todayRounds: todayRows.filter(played).length,
    todayXp: todayRows.reduce(function (a, g) { return a + (Number(g.XP) || 0); }, 0),
    dayCap: GAME_XP.dayCap,
    weekRounds: weekRows.filter(played).length,
    weekAvg: pct(weekRows),
    total: rows.filter(played).length,
    recent: recent,
    review: dueReview(kid.Name, t),
    saved: saver ? wordsOf(kid.Name).saved : null
  };
}

// Review state per kid, one cell: "id|box|due id|box|due ...". Only items missed at least once.
function readReview(name) {
  var row = readTable('Review').filter(function (r) { return r.Girl === name; })[0];
  var map = {};
  String(row ? row.Items : '').split(' ').forEach(function (p) {
    var a = p.split('|');
    if (a.length === 3) map[a[0]] = { box: Number(a[1]) || 1, due: a[2] };
  });
  return map;
}

function updateReview(name, missed, right, t) {
  var map = readReview(name), changed = false;
  missed.forEach(function (id) { map[id] = { box: 1, due: addDays(t, REVIEW_DAYS[0]) }; changed = true; });
  right.forEach(function (id) {
    var e = map[id];
    if (!e) return;
    changed = true;
    if (e.box >= REVIEW_DAYS.length) { delete map[id]; return; }
    map[id] = { box: e.box + 1, due: addDays(t, REVIEW_DAYS[e.box]) };
  });
  if (changed) writeReview(name, map);
}

function writeReview(name, map) {
  var ids = Object.keys(map).sort(function (a, b) { return map[a].due < map[b].due ? -1 : 1; }).slice(0, 300);
  upsertRow('Review', 'Girl', name, { Items: ids.map(function (id) { return id + '|' + map[id].box + '|' + map[id].due; }).join(' ') });
}

// A word saved with the Word Saver comes back tomorrow (unless it is already in her review).
function reviewAdd(name, id, t) {
  var map = readReview(name);
  if (map[id]) return;
  map[id] = { box: 1, due: addDays(t, REVIEW_DAYS[0]) };
  writeReview(name, map);
}

function dueReview(name, t) {
  var map = readReview(name);
  return Object.keys(map).filter(function (id) { return map[id].due <= t; })
    .sort(function (a, b) { return map[a].due < map[b].due ? -1 : 1; }).slice(0, 30);
}

// ---------- Journey ----------

// Where a kid is on the map. Her stations are the tasks logged since she entered this world:
// each passed gate (Gates tab) stores how many tasks she had logged by then.
function journeyInfo(kid, t) {
  var lv = LEVELS.indexOf(kid.Level) >= 0 ? kid.Level : 'a2';
  var next = LEVELS[LEVELS.indexOf(lv) + 1] || null;
  var tasks = readTable('Log').filter(function (l) { return l.Girl === kid.Name && l.Section !== 'level'; });
  var gates = readTable('Gates').filter(function (g) { return g.Girl === kid.Name; });
  var lastPass = -1;
  gates.forEach(function (g, i) { if (g.Passed === 'yes') lastPass = i; });
  var mine = tasks.slice(lastPass >= 0 ? Number(gates[lastPass].Tasks) || 0 : 0);
  var tries = gates.slice(lastPass + 1), last = tries[tries.length - 1];
  var n = mine.length, avg = avgPercent(mine);
  var ready = n >= JOURNEY.stations || (n >= JOURNEY.early && avg !== null && avg >= JOURNEY.earlyAvg);
  var until = last ? addDays(last.Date, JOURNEY.waitDays) : null;
  var state = !next ? 'top' : !ready ? 'locked' : until && until > t ? 'wait' : 'open';
  return {
    level: lv, label: LEVEL_LABEL[lv], world: LEVELS.indexOf(lv) + 1, name: WORLDS[lv],
    stations: n, goal: JOURNEY.stations, early: JOURNEY.early, earlyAvg: JOURNEY.earlyAvg, avg: avg, tasks: tasks.length,
    done: mine.slice(0, JOURNEY.stations).map(function (l) {
      return { s: l.Section, p: l.Percent === '' || l.Percent === null ? null : Number(l.Percent) };
    }),
    gate: {
      state: state, next: next, nextLabel: next ? LEVEL_LABEL[next] : null, nextName: next ? WORLDS[next] : null,
      items: JOURNEY.items, need: gateNeed(), until: state === 'wait' ? until : null, tries: tries.length,
      last: last ? { correct: Number(last.Correct), total: Number(last.Total), date: last.Date } : null
    },
    worlds: LEVELS.map(function (l) { return { level: l, label: LEVEL_LABEL[l], name: WORLDS[l] }; }),
    passed: gates.filter(function (g) { return g.Passed === 'yes'; }).map(function (g) { return { from: g.From, to: g.To, date: g.Date }; })
  };
}

function gateNeed() { return Math.ceil(JOURNEY.items * JOURNEY.pass / 100); }

// One gate challenge, scored in the app like the games. Passing raises the kid's level: her next
// daily tasks and games come from the new level, and the map starts the next world.
function apiGateResult(name, pin, correct, total, missed, right) {
  var kid = auth(name, pin);
  if (pendingLevelTest(kid)) throw new Error('Take the level test first.');
  correct = Math.round(Number(correct));
  total = Math.round(Number(total));
  if (!(total === JOURNEY.items && correct >= 0 && correct <= total)) throw new Error('Invalid score');
  missed = cleanIds(missed, JOURNEY.items);
  right = cleanIds(right, JOURNEY.items);
  var t = today(), row;
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    invalidate('Gates');
    var j = journeyInfo(kid, t);
    if (j.gate.state === 'wait') throw new Error('The gate opens again on ' + j.gate.until + '.');
    if (j.gate.state !== 'open') throw new Error('The gate is not open yet.');
    var passed = correct >= j.gate.need;
    row = { Timestamp: new Date(), Girl: kid.Name, Date: t, From: j.level, To: j.gate.next, Correct: correct, Total: total,
      Passed: passed ? 'yes' : 'no', Tasks: j.tasks, XP: passed ? JOURNEY.xp : correct * GAME_XP.right };
    appendRow('Gates', row);
    if (passed) setGirlField(kid.Name, 'Level', j.gate.next);
    updateReview(kid.Name, missed, right, t);
  } finally {
    lock.releaseLock();
  }
  try { notifyGate(kid, row); } catch (e) { console.error(e); }
  var dash = buildDashboard(findGirl(kid.Name));
  dash.gateResult = { passed: row.Passed === 'yes', correct: correct, total: total, from: row.From, to: row.To, xp: row.XP };
  return dash;
}

// The admin PIN (Settings) sees every group; a group's ParentPIN sees only that group.
function apiParent(pin) {
  ensureSetup();
  var access = parentAccess(pin);
  if (access.isAdmin) auditOpen('admin', 'admin', ''); else auditOpen('parent', access.group.Name, String(access.group.Id));
  return parentData(access.isAdmin ? groups() : [access.group], access.isAdmin, access.isAdmin ? 'admin' : String(access.group.Id));
}

function parentAccess(pin) {
  pin = String(pin).trim();
  var isAdmin = pin === String(getSetting('AdminPIN')).trim();
  var group = isAdmin ? null : groups().filter(function (g) { return String(g.ParentPIN || '').trim() && String(g.ParentPIN).trim() === pin; })[0];
  checkPin('parent', isAdmin || !!group);
  return { isAdmin: isAdmin, group: group };
}

function parentData(list, isAdmin, who) {
  var t = today();
  var logs = readTable('Log');
  var out = list.map(function (g) {
    var id = String(g.Id);
    var kids = kidsIn(id).map(function (k) {
      var d = buildDashboard(k);
      var start = kidStart(k);
      var history = [];
      for (var w = 5; w >= 0; w--) {
        var ref = addDays(weekStart(t), -7 * w);
        if (ref < weekStart(start)) continue;
        var dates = weekDates(ref).filter(function (x) { return x >= start && x <= t; });
        var wl = logs.filter(function (l) { return l.Girl === k.Name && dates.indexOf(l.Date) >= 0; });
        history.push({ week: ref, done: wl.length, expected: dates.length, avg: avgPercent(wl) });
      }
      d.history = history;
      d.recent = logs.filter(function (l) { return l.Girl === k.Name; }).slice(-8).reverse().map(function (l) {
        return { date: l.Date, doneOn: l.DoneOn, section: l.Section, title: l.Title, url: l.URL, correct: l.Correct, total: l.Total, percent: l.Percent, points: l.Points,
          mission: l.Mission || '', seconds: Number(l.Seconds) || null };
      });
      d.email = k.Email;
      d.bought = shopBought(readTable('Shop').filter(function (r) { return r.Girl === k.Name; }), 3);
      d.pin = String(k.PIN);
      return d;
    });
    return {
      id: id,
      name: g.Name,
      link: groupLink(id),
      parentPin: isAdmin ? String(g.ParentPIN || '') : undefined,
      email: g.Email,
      goal: {
        goal: Number(g.Goal) || 1500,
        total: kids.reduce(function (a, d) { return a + d.stats.earned; }, 0),
        reward: g.GoalReward || ''
      },
      girls: kids
    };
  });
  return {
    isAdmin: !!isAdmin,
    groups: out,
    sheetUrl: isAdmin ? SpreadsheetApp.getActive().getUrl() : null,
    settings: isAdmin ? { reminderHour: Number(getSetting('ReminderHour')) || 17, lastCallHour: Number(getSetting('LastCallHour')) || null } : null,
    push: {
      key: vapidPublicKey(),
      summaryHour: Number(getSetting('ParentSummaryHour')) || 21,
      devices: readTable('ParentPush').filter(function (r) { return r.Who === who; }).map(function (r) { return { e: r.Endpoint, instant: r.Instant !== 'no' }; })
    },
    // Coco's Nest last: the admin can add a kid aged 2 to 7 (her age goes in the age field).
    levels: LEVELS.map(function (l) { return { id: l, label: LEVEL_LABEL[l] }; }).concat([{ id: 'nest', label: LEVEL_LABEL.nest }]),
    today: t,
    word: wordOfDay(t)
  };
}

// ---------- Admin actions ----------

function apiAdminAddGroup(pin, name, email) {
  ensureSetup();
  if (!parentAccess(pin).isAdmin) throw new Error('Only the admin can add groups');
  name = String(name || '').trim();
  if (!name) throw new Error('Enter a group name');
  if (groups().some(function (g) { return String(g.Name).toLowerCase() === name.toLowerCase(); })) throw new Error('A group with this name already exists');
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  var id, parentPin;
  try {
    var ids = groups().map(function (g) { return String(g.Id); });
    do { id = Math.random().toString(36).slice(2, 8); } while (ids.indexOf(id) >= 0);
    parentPin = uniqueParentPin();
    appendRow('Groups', { Id: id, Name: name, ParentPIN: parentPin, Goal: 1500, GoalReward: 'Pizza party for the group', Email: String(email || '').trim() });
  } finally {
    lock.releaseLock();
  }
  audit('admin', 'admin', id, 'add family', name);
  var data = apiParent(pin);
  data.created = { type: 'group', name: name, pin: parentPin, link: groupLink(id) };
  return data;
}

// missions: 'no' keeps the new kid's daily task on test-english.com (the old way); otherwise Today's Mission.
function apiAdminAddKid(pin, name, age, groupId, level, missions) {
  ensureSetup();
  if (!parentAccess(pin).isAdmin) throw new Error('Only the admin can add kids');
  name = String(name || '').trim();
  if (!name) throw new Error('Enter a name');
  if (findGirl(name)) throw new Error('This name is already taken — add a last-name initial');
  if (!findGroup(groupId)) throw new Error('Choose a group');
  if (LEVELS.indexOf(level) < 0 && level !== 'nest') level = 'a2';
  var kidPin = randomPin();
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    var count = readTable('Girls').length;
    appendRow('Girls', { Name: name, Age: Number(age) || '', PIN: kidPin, Level: level, Email: '', Redeemed: 0, Color: COLORS[count % COLORS.length], Group: groupId,
      Missions: String(missions || '').trim().toLowerCase() === 'no' ? 'no' : '' });
  } finally {
    lock.releaseLock();
  }
  audit('admin', 'admin', groupId, 'add kid', name + ' · ' + level);
  var data = apiParent(pin);
  data.created = { type: 'kid', name: name, pin: kidPin, link: groupLink(groupId), group: findGroup(groupId).Name };
  return data;
}

// Reminder times (hours, Asia/Jerusalem). An empty last call turns it off.
function apiAdminSettings(pin, reminderHour, lastCallHour) {
  ensureSetup();
  if (!parentAccess(pin).isAdmin) throw new Error('Only the admin can change settings');
  var r = Number(reminderHour), l = lastCallHour === '' || lastCallHour === null ? '' : Number(lastCallHour);
  if (!(r >= 0 && r <= 23)) throw new Error('Choose a reminder hour');
  if (l !== '' && !(l >= 0 && l <= 23)) throw new Error('Choose a last-call hour');
  if (l !== '' && l <= r) throw new Error('Last call must be later than the daily reminder');
  setSetting('ReminderHour', String(r));
  setSetting('LastCallHour', String(l));
  installTriggers();
  audit('admin', 'admin', '', 'reminder hours', r + ':00' + (l === '' ? ', no last call' : ', last call ' + l + ':00'));
  return apiParent(pin);
}

// The admin sets a family's parents' code (4 digits, unused by another family or the admin).
function apiAdminParentPin(pin, groupId, newPin) {
  ensureSetup();
  if (!parentAccess(pin).isAdmin) throw new Error('Only the admin can change settings');
  newPin = String(newPin || '').trim();
  if (!/^\d{4}$/.test(newPin)) throw new Error('A parents code is 4 digits');
  var gs = groups(), g = gs.filter(function (x) { return String(x.Id) === String(groupId); })[0];
  if (!g) throw new Error('Unknown family');
  if (newPin === String(getSetting('AdminPIN')) || gs.some(function (x) { return x !== g && String(x.ParentPIN) === newPin; })) throw new Error('This code is taken');
  invalidate('Groups');
  var sh = sheet('Groups'), values = sh.getDataRange().getValues(), col = values[0].indexOf('ParentPIN');
  for (var i = 1; i < values.length; i++) if (String(values[i][0]) === String(g.Id)) sh.getRange(i + 1, col + 1).setValue(newPin);
  invalidate('Groups');
  audit('admin', 'admin', String(g.Id), 'parents code', g.Name);
  return { ok: true };
}

function uniqueParentPin() {
  var taken = groups().map(function (g) { return String(g.ParentPIN); }).concat([String(getSetting('AdminPIN'))]);
  var p;
  do { p = randomPin(); } while (taken.indexOf(p) >= 0);
  return p;
}

// ---------- Dashboard ----------

// A kid's first day = her first assignment (the level test). New kids start today.
function kidStart(kid) {
  var dates = readTable('Assignments').filter(function (a) { return a.Girl === kid.Name; }).map(function (a) { return a.Date; }).sort();
  return dates.length ? dates[0] : today();
}

// New kids (nothing logged yet) do the level test before anything else: no daily tasks and no
// games until it is logged. Returns the pending test ({date, title, url}) or null.
function pendingLevelTest(kid) {
  if (readTable('Log').some(function (l) { return l.Girl === kid.Name; })) return null;
  var start = kidStart(kid);
  var a = ensureAssignments(kid, [start])[start];
  return a && a.section === 'level' ? { date: start, title: a.title, url: a.url } : null;
}

// Today's task for reminders: the pending level test, otherwise today's assignment.
function todayTask(kid) {
  var lt = pendingLevelTest(kid);
  if (lt) return { section: 'level', level: '', title: lt.title, url: lt.url };
  var t = today();
  return ensureAssignments(kid, [t])[t];
}

function buildDashboard(kid) {
  var t = today();
  var pending = pendingLevelTest(kid);
  var start = kidStart(kid);
  var dates = weekDates(t);
  var active = pending ? [] : dates.filter(function (d) { return d >= start && d <= t; });
  var assigned = ensureAssignments(kid, active);
  var logs = readTable('Log').filter(function (l) { return l.Girl === kid.Name; });
  var byDate = {};
  // A Nest day can have more lessons (one more lesson): the day shows its own, the first one.
  logs.forEach(function (l) { if (!byDate[l.Date] || l.Section !== 'nest') byDate[l.Date] = l; });
  var missions = !pending && missionsOn(kid), nest = isNest(kid);

  var week = dates.map(function (d) {
    var wd = parseDate(d).getDay();
    var item = { date: d, day: DAY_NAMES[wd], isToday: d === t, isFuture: d > t,
      beforeStart: d < start || (!!pending && d !== pending.date) };
    var sec = assigned[d] ? assigned[d].section : sectionFor(d);
    item.section = sec;
    item.label = SECTIONS[sec].label;
    if (assigned[d]) {
      item.title = assigned[d].title;
      item.url = assigned[d].url;
      item.level = LEVEL_LABEL[assigned[d].level] || '';
      item.mission = missionView(kid, assigned[d], missions);
    }
    var l = byDate[d];
    if (l) {
      item.done = true;
      item.correct = l.Correct; item.total = l.Total; item.percent = l.Percent; item.points = l.Points;
      if (l.Mission) item.seconds = Number(l.Seconds) || null;
      item.late = l.DoneOn !== l.Date;
      if (sec === 'level') item.levelResult = LEVEL_LABEL[l.Level] || '';
    }
    return item;
  });

  var earned = totalPoints(logs, start);
  var redeemed = Number(kid.Redeemed) || 0;
  var owned = ownedItems(kid.Name), shield = !!owned['streak-shield'], run = streakInfo(logs, t, shield);
  var balance = earned - redeemed;
  var rewards = rewardsFor(groupOf(kid));
  var next = rewards.filter(function (r) { return r.points > balance; })[0] || null;

  return {
    // inApp: the level test is played in the app (Pilot.js); kids on the old link keep test-english.com's test.
    girl: { name: kid.Name, level: kid.Level, levelLabel: LEVEL_LABEL[kid.Level] || kid.Level, color: kid.Color, inApp: missionsOn(kid), age: Number(kid.Age) || null },
    today: t,
    week: week,
    stats: {
      earned: earned, redeemed: redeemed, balance: balance,
      streak: run.days, shield: shield, saved: run.saved,
      weekDone: week.filter(function (d) { return d.done; }).length,
      weekTotal: week.filter(function (d) { return !d.beforeStart; }).length,
      avg: avgPercent(logs),
      total: logs.length
    },
    rewards: rewards,
    nextReward: next,
    levelTest: pending,
    journey: pending || nest ? null : journeyInfo(kid, t),
    nest: nest ? nestInfo(kid, t, assigned, logs) : null,
    pet: petInfo(kid),
    placement: placementInfo(kid),
    games: gameStats(kid, t, owned['word-saver']),
    chat: pending || nest ? null : chatInfo(kid, t),
    coins: coinsOf(kid).balance,
    upgrades: upgradesOf(owned),
    polish: polishInfo(kid),
    shop: { open: !nest && shopOpenFor(kid, t), opens: shopOpens(), season: shopSeason(t) },
    push: { key: vapidPublicKey(), devices: readTable('Push').filter(function (s) { return s.Girl === kid.Name; }).length },
    word: wordOfDay(t)
  };
}

function totalPoints(logs, start) {
  var sum = 0;
  var weeks = {};
  logs.forEach(function (l) {
    sum += Number(l.Points) || 0;
    var ws = weekStart(l.Date);
    (weeks[ws] = weeks[ws] || {})[l.Date] = true;
  });
  // Full-week bonus: every day of the week (from the kid's first day) done.
  Object.keys(weeks).forEach(function (ws) {
    var expected = weekDates(ws).filter(function (d) { return d >= start; });
    if (expected.every(function (d) { return weeks[ws][d]; })) sum += WEEK_BONUS;
  });
  return sum;
}

function streak(logs, t, shield) { return streakInfo(logs, t, shield).days; }

// Days in a row with a task done (today does not break it until the day is over). With the Streak Shield
// (Shop.js), one missed day per week (Sun-Sat) between two practiced days is saved: it keeps the streak alive
// but does not add to it. saved = the saved days of this week.
function streakInfo(logs, t, shield) {
  var doneDays = {}, used = {}, saved = [];
  logs.forEach(function (l) { doneDays[l.DoneOn] = true; });
  var d = doneDays[t] ? t : addDays(t, -1);
  var n = 0;
  for (;;) {
    if (doneDays[d]) { n++; d = addDays(d, -1); continue; }
    var prev = addDays(d, -1), ws = weekStart(d);
    if (!shield || used[ws] || !doneDays[prev]) break;
    used[ws] = true;
    if (ws === weekStart(t)) saved.push(d);
    d = prev;
  }
  return { days: n, saved: saved };
}

function avgPercent(logs) {
  var s = logs.filter(function (l) { return l.Percent !== '' && l.Percent !== null && l.Section !== 'level'; });
  if (!s.length) return null;
  return Math.round(s.reduce(function (a, l) { return a + Number(l.Percent); }, 0) / s.length);
}

function wordOfDay(d) {
  var i = Math.abs(daysBetween(START_DATE, d)) % WORDS.length;
  return { word: WORDS[i][0], meaning: WORDS[i][1] };
}

// ---------- Assignments ----------

function sectionFor(d) {
  var wd = parseDate(d).getDay();
  var s = ROTATION[wd];
  if (s === 'FRIDAY') {
    var wi = Math.round(daysBetween(weekStart(START_DATE), weekStart(d)) / 7);
    s = wi % 2 === 0 ? 'use-of-english' : 'writing';
  }
  return s;
}

// Returns {date: assignment} for the requested dates, creating missing ones.
// A kid's very first assignment is always the level test.
function ensureAssignments(kid, dates) {
  var out = {};
  var used = {};
  var collect = function (rows) {
    rows.forEach(function (a) {
      if (a.Girl !== kid.Name) return;
      used[a.URL] = true;
      out[a.Date] = { section: a.Section, level: a.Level, title: a.Title, url: a.URL };
    });
  };
  collect(readTable('Assignments'));
  var missing = dates.filter(function (d) { return !out[d]; }).sort();
  if (!missing.length) return out;

  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    collect(readTableUncached('Assignments'));
    missing = missing.filter(function (d) { return !out[d]; });
    var first = Object.keys(out).length === 0, missions = missionsOn(kid);
    missing.forEach(function (d, i) {
      // A Nest kid (ages 2 to 7) gets the next unit of Coco's Nest and never the level test.
      var a = isNest(kid) ? nestNext(kid) : first && i === 0 ? LEVEL_TEST : nextExercise(sectionFor(d), kid.Level, used, missions);
      used[a.url] = true;
      out[d] = a;
      appendRow('Assignments', { Girl: kid.Name, Date: d, Section: a.section, Level: a.level, Title: a.title, URL: a.url });
    });
  } finally {
    lock.releaseLock();
  }
  return out;
}

// missions: Today's Mission is on for the kid, so a topic of her level that has a mission comes first
// (Missions.js); without one left, the usual next topic (a link).
function nextExercise(section, level, used, missions) {
  var byLevel = CATALOG[section];
  var start = Math.max(0, LEVELS.indexOf(level));
  if (missions) {
    // Writing has no missions yet, and C1 has no Use of English: a kid with missions gets a Use of English (or a
    // grammar) mission that day instead of a link out of the app.
    var tries = section === 'writing' || section === 'use-of-english' ? [section, 'use-of-english', 'grammar'] : [section];
    for (var s = 0; s < tries.length; s++) {
      var own = (CATALOG[tries[s]] || {})[LEVELS[start]] || [];
      for (var k = 0; k < own.length; k++) {
        if (!used[own[k].u] && missionOf(own[k].u)) return { section: tries[s], level: LEVELS[start], title: own[k].t, url: own[k].u };
      }
    }
  }
  for (var i = start; i < LEVELS.length; i++) {
    var list = byLevel[LEVELS[i]] || [];
    for (var j = 0; j < list.length; j++) {
      if (!used[list[j].u]) return { section: section, level: LEVELS[i], title: list[j].t, url: list[j].u };
    }
  }
  // Everything done: repeat from the kid's level.
  var lv = byLevel[LEVELS[start]] ? LEVELS[start] : Object.keys(byLevel)[0];
  var pick = byLevel[lv][Math.floor(Math.random() * byLevel[lv].length)];
  return { section: section, level: lv, title: pick.t, url: pick.u };
}

// ---------- Reminders (time-driven triggers) ----------

function dailyReminder() {
  try { pushReminders(false); } catch (e) { console.error(e); }
  var t = today();
  var logs = readTable('Log');
  readTable('Girls').forEach(function (k) {
    if (!k.Email) return;
    var done = logs.some(function (l) { return l.Girl === k.Name && l.Date === t; });
    if (done) return;
    var a = todayTask(k);
    MailApp.sendEmail({
      to: k.Email,
      subject: k.Name + ', your 10 minutes of English are waiting!',
      htmlBody: '<p>Hi ' + k.Name + ',</p><p>Today: <b>' + SECTIONS[a.section].label + '</b> — ' + a.title + '</p>' +
        '<p><a href="' + groupLink(groupOf(k)) + '">Open English with Coco</a> and keep your streak going.</p>'
    });
  });
}

// Fridays: the owner gets every group; each group with an Email gets its own summary.
function weeklySummary() {
  var data = parentData(groups(), true, 'admin');
  var owner = Session.getEffectiveUser().getEmail();
  if (owner) {
    MailApp.sendEmail({ to: owner, subject: 'English with Coco — weekly summary ' + data.today, htmlBody: data.groups.map(summaryHtml).join('<hr>') });
  }
  data.groups.forEach(function (g) {
    if (g.email) MailApp.sendEmail({ to: g.email, subject: 'English with Coco — ' + g.name + ' weekly summary', htmlBody: summaryHtml(g) });
  });
}

function summaryHtml(g) {
  var rows = g.girls.map(function (d) {
    return '<tr><td><b>' + d.girl.name + '</b></td><td>' + d.stats.weekDone + '/' + d.stats.weekTotal + '</td><td>' +
      (d.stats.avg === null ? '–' : d.stats.avg + '%') + '</td><td>' + d.stats.streak + '</td><td>' + d.stats.balance + '</td><td>' + d.girl.levelLabel +
      (d.journey ? ' · ' + Math.min(d.journey.stations, d.journey.goal) + '/' + d.journey.goal + (d.journey.gate.state === 'open' ? ' (gate open)' : '') : '') + '</td><td>' +
      d.games.weekRounds + (d.games.weekAvg === null ? '' : ' (' + d.games.weekAvg + '%)') + '</td></tr>';
  }).join('');
  return '<h3>' + g.name + '</h3><table cellpadding="6" border="1" style="border-collapse:collapse"><tr><th>Name</th><th>Week</th><th>Avg</th><th>Streak</th><th>Points</th><th>Level</th><th>Games</th></tr>' +
    rows + '</table><p>Group goal: ' + g.goal.total + ' / ' + g.goal.goal + '</p><p><a href="' + g.link + '">Open English with Coco</a></p>';
}

function installTriggers() {
  ScriptApp.getProjectTriggers().forEach(function (tr) {
    var f = tr.getHandlerFunction();
    if (f === 'dailyReminder' || f === 'lastCallReminder' || f === 'parentSummary' || f === 'weeklySummary' || f === 'warmCache') ScriptApp.deleteTrigger(tr);
  });
  var hour = Number(getSetting('ReminderHour')) || 17;
  ScriptApp.newTrigger('dailyReminder').timeBased().everyDays(1).atHour(hour).inTimezone(TZ).create();
  var last = Number(getSetting('LastCallHour'));
  if (last) ScriptApp.newTrigger('lastCallReminder').timeBased().everyDays(1).atHour(last).inTimezone(TZ).create();
  var summary = Number(getSetting('ParentSummaryHour'));
  if (summary) ScriptApp.newTrigger('parentSummary').timeBased().everyDays(1).atHour(summary).inTimezone(TZ).create();
  ScriptApp.newTrigger('weeklySummary').timeBased().onWeekDay(ScriptApp.WeekDay.FRIDAY).atHour(12).inTimezone(TZ).create();
  ScriptApp.newTrigger('warmCache').timeBased().everyMinutes(WARM.everyMin).create();
}

// Every 10 minutes during the day: refills the tables the cache lost (after 6 hours, or after a write), so
// the first kid of the morning, or after a quiet hour, does not wait for the sheet. About 2 minutes of the
// 90 minutes of trigger time a day.
var WARM = { everyMin: 10, from: 7, to: 22, tables: ['Girls', 'Groups', 'Settings', 'Rewards', 'Assignments', 'Log', 'Games', 'Review', 'Gates', 'Duels', 'Duos', 'Bonus', 'Push', 'Shop', 'Wardrobe', 'Words'] };
function warmCache() {
  auditFlush();
  var h = Number(Utilities.formatDate(new Date(), TZ, 'H'));
  if (h < WARM.from || h >= WARM.to) return;
  ensureSetup();
  WARM.tables.forEach(readTable);
}

// ---------- Setup & migrations ----------

function ensureSetup() {
  // A cache flag first: duels poll often, and Script Properties reads have a daily quota.
  var cache = CacheService.getScriptCache();
  if (cache.get('SETUP') === SETUP_VERSION) return;
  var props = PropertiesService.getScriptProperties();
  if (props.getProperty('setup') === SETUP_VERSION) { cache.put('SETUP', SETUP_VERSION, 21600); return; }
  var lock = LockService.getScriptLock();
  lock.waitLock(30000);
  try {
    if (props.getProperty('setup') === SETUP_VERSION) return;
    var ss = SpreadsheetApp.getActive();
    ss.setSpreadsheetTimeZone(TZ);
    Object.keys(HEADERS).forEach(function (name) {
      var sh = ss.getSheetByName(name) || ss.insertSheet(name);
      if (sh.getLastRow() === 0) {
        sh.getRange(1, 1, 1, HEADERS[name].length).setValues([HEADERS[name]]).setFontWeight('bold');
        sh.setFrozenRows(1);
      } else {
        // Add columns introduced by later versions.
        var head = sh.getRange(1, 1, 1, Math.max(1, sh.getLastColumn())).getValues()[0];
        HEADERS[name].forEach(function (h) {
          if (head.indexOf(h) < 0) {
            head.push(h);
            sh.getRange(1, head.length).setValue(h).setFontWeight('bold');
          }
        });
      }
      sh.getRange('A:Z').setNumberFormat('@');
    });
    var stray = ss.getSheetByName('Sheet1') || ss.getSheetByName('גיליון1');
    if (stray && ss.getSheets().length > 1) ss.deleteSheet(stray);
    clearCache();

    var defaults = { AdminPIN: randomPin(), ReminderHour: '17', LastCallHour: '20', ParentSummaryHour: '21', FamilyGoal: '1500', FamilyReward: 'Family pizza & movie night out', AppUrl: '', PublicUrl: PUBLIC_URL, PilotFrom: today(), ShopOpens: SHOP.opens, ShopEarly: '',
      InviteCode: Math.random().toString(36).slice(2, 8), InviteOpen: 'no', TeacherCode: String(100000 + Math.floor(Math.random() * 900000)) };
    Object.keys(defaults).forEach(function (k) { if (getSetting(k) === null) setSetting(k, defaults[k]); });
    if (getSetting('AppUrl') !== APP_URL) setSetting('AppUrl', APP_URL);
    // v18: the front end moved from GitHub Pages to its own address (the old one shows a "new home" screen).
    if (/github\.io/.test(String(getSetting('PublicUrl') || ''))) setSetting('PublicUrl', PUBLIC_URL);
    // v15: Today's Mission is every kid's daily task (Girls.Missions = no keeps the old link), so the pilot setting goes.
    var st = sheet('Settings'), sv = st.getDataRange().getValues();
    for (var si = sv.length - 1; si >= 1; si--) if (sv[si][0] === 'MissionPilot') st.deleteRow(si + 1);
    invalidate('Settings');

    // v3: groups. The existing family becomes the first (default) group.
    if (readTableUncached('Groups').length === 0) {
      appendRow('Groups', { Id: 'family', Name: 'Family', ParentPIN: '', Goal: getSetting('FamilyGoal') || 1500, GoalReward: getSetting('FamilyReward') || '', Email: '' });
    }
    var firstId = String(readTableUncached('Groups')[0].Id);
    var gs = sheet('Girls');
    if (readTableUncached('Girls').length === 0) {
      [['Ziv', 15, 'b1', '#7b7ff7'], ['Ron', 14, 'b1', '#3cc7b6'], ['Aviv', 12, 'a2', '#f6a04d']].forEach(function (r) {
        appendRow('Girls', { Name: r[0], Age: r[1], PIN: randomPin(), Level: r[2], Redeemed: 0, Color: r[3], Group: firstId });
      });
    } else {
      var values = gs.getDataRange().getValues();
      var col = values[0].indexOf('Group');
      for (var i = 1; i < values.length; i++) {
        if (values[i].join('') !== '' && !String(values[i][col]).trim()) gs.getRange(i + 1, col + 1).setValue(firstId);
      }
    }
    if (readTableUncached('Rewards').length === 0) {
      [[60, 'Choose the Friday dessert'], [120, '30 extra minutes of screen time'], [200, 'Skip one chore of your choice'],
       [300, 'Ice cream / coffee date with Dad'], [450, 'Pick the family movie night + snacks'], [650, '₪75 gift card'],
       [1000, 'Outing of your choice — escape room, bowling…']].forEach(function (r) {
        appendRow('Rewards', { Points: r[0], Reward: r[1] });
      });
    }

    clearCache();
    installTriggers();
    props.setProperty('setup', SETUP_VERSION);
    cache.put('SETUP', SETUP_VERSION, 21600);
  } finally {
    lock.releaseLock();
  }
}

// ---------- Sheet helpers ----------

function sheet(name) { return SpreadsheetApp.getActive().getSheetByName(name); }

// Two cache levels: TABLES lives for one request; CacheService survives across requests
// (sheet reads cost 0.3-1s each). Every table stays 6 hours, the most CacheService keeps: each write and
// each manual edit (onEdit) clears it, and the warmCache trigger refills it during the day.
var TABLES = {};
var CACHE_SEC = 21600;
var CHUNK = 30000;

function readTable(name) {
  if (!TABLES[name]) TABLES[name] = cacheGet(name) || cacheFill(name);
  return TABLES[name];
}

// A read from the sheet goes into the cache only if no write happened while it was being read; a
// copy from before a write would otherwise stay for hours. invalidate() moves the version stamp.
function cacheFill(name) {
  var c = CacheService.getScriptCache(), v0 = null;
  try { v0 = c.get('V:' + name); } catch (e) {}
  var rows = readTableUncached(name);
  cachePut(name, rows);
  try { if (c.get('V:' + name) !== v0) c.remove('T:' + name); } catch (e) {}
  return rows;
}

function cacheGet(name) {
  try {
    var c = CacheService.getScriptCache();
    var n = Number(c.get('T:' + name));
    if (!n) return null;
    var keys = [];
    for (var i = 0; i < n; i++) keys.push('T:' + name + ':' + i);
    var parts = c.getAll(keys), s = '';
    for (var k = 0; k < keys.length; k++) {
      if (parts[keys[k]] === undefined) return null;
      s += parts[keys[k]];
    }
    return JSON.parse(s);
  } catch (e) {
    return null;
  }
}

function cachePut(name, rows) {
  try {
    var s = JSON.stringify(rows), obj = {}, n = Math.max(1, Math.ceil(s.length / CHUNK));
    for (var i = 0; i < n; i++) obj['T:' + name + ':' + i] = s.substr(i * CHUNK, CHUNK);
    obj['T:' + name] = String(n);
    CacheService.getScriptCache().putAll(obj, CACHE_SEC);
  } catch (e) {}
  return rows;
}

function invalidate(name) {
  delete TABLES[name];
  try {
    var c = CacheService.getScriptCache();
    c.put('V:' + name, Date.now() + ':' + Math.random(), CACHE_SEC);
    c.remove('T:' + name);
  } catch (e) {}
}

function clearCache() {
  TABLES = {};
  try { CacheService.getScriptCache().removeAll(Object.keys(HEADERS).map(function (n) { return 'T:' + n; })); } catch (e) {}
}

// Simple trigger: any manual edit in the spreadsheet (PIN, level, rewards...) drops the cache.
function onEdit(e) {
  clearCache();
  auditSheetEdit(e);
}

function readTableUncached(name) {
  var sh = sheet(name);
  if (!sh || sh.getLastRow() < 2) return [];
  var values = sh.getRange(1, 1, sh.getLastRow(), sh.getLastColumn()).getValues();
  var head = values[0];
  return values.slice(1).filter(function (r) { return r.join('') !== ''; }).map(function (r) {
    var o = {};
    head.forEach(function (h, i) { if (h) o[h] = r[i] instanceof Date && h !== 'Timestamp' ? fmt(r[i]) : r[i]; });
    ['Name', 'Group', 'Id'].forEach(function (k) { if (o[k] !== undefined) o[k] = String(o[k]).trim(); });
    if (o.Level !== undefined) o.Level = String(o.Level).trim().toLowerCase().replace('b1+', 'b1-b2');
    return o;
  });
}

// Writes by header name, so it works whatever the column order in the sheet is.
function appendRow(name, obj) {
  var sh = sheet(name);
  var head = sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0];
  sh.appendRow(head.map(function (h) { return obj[h] === undefined ? '' : obj[h]; }));
  invalidate(name);
}

function findGirl(name) {
  return readTable('Girls').filter(function (g) { return g.Name.toLowerCase() === String(name).toLowerCase(); })[0];
}

function setGirlField(name, field, value) {
  var fields = {};
  fields[field] = value;
  setGirlFields(name, fields);
}

function setGirlFields(name, fields) {
  invalidate('Girls');
  var sh = sheet('Girls');
  var values = sh.getDataRange().getValues();
  for (var i = 1; i < values.length; i++) {
    if (String(values[i][0]).trim() !== name) continue;
    Object.keys(fields).forEach(function (f) {
      var col = values[0].indexOf(f);
      if (col >= 0) sh.getRange(i + 1, col + 1).setValue(fields[f]);
    });
  }
  invalidate('Girls');
}

// Moves a kid's assignment to another date (used for a level test done after the day it was given).
function moveAssignment(name, from, to) {
  invalidate('Assignments');
  var sh = sheet('Assignments');
  var values = sh.getDataRange().getValues();
  var head = values[0], g = head.indexOf('Girl'), d = head.indexOf('Date');
  for (var i = 1; i < values.length; i++) {
    var date = values[i][d] instanceof Date ? fmt(values[i][d]) : String(values[i][d]);
    if (String(values[i][g]).trim() === name && date === from) { sh.getRange(i + 1, d + 1).setValue(to); invalidate('Assignments'); return; }
  }
}

// Removes a kid's assignments except the one on keepDate.
function dropAssignmentsExcept(name, keepDate) {
  invalidate('Assignments');
  var sh = sheet('Assignments');
  var values = sh.getDataRange().getValues();
  var head = values[0], g = head.indexOf('Girl'), d = head.indexOf('Date');
  for (var i = values.length - 1; i >= 1; i--) {
    var date = values[i][d] instanceof Date ? fmt(values[i][d]) : String(values[i][d]);
    if (String(values[i][g]).trim() === name && date !== keepDate) sh.deleteRow(i + 1);
  }
  invalidate('Assignments');
}

// Updates the row whose keyField equals key (by header name), or appends one.
function upsertRow(name, keyField, key, fields) {
  invalidate(name);
  var sh = sheet(name);
  var values = sh.getDataRange().getValues();
  var head = values[0], k = head.indexOf(keyField);
  for (var i = 1; i < values.length; i++) {
    if (String(values[i][k]).trim() !== key) continue;
    Object.keys(fields).forEach(function (f) {
      var col = head.indexOf(f);
      if (col >= 0) sh.getRange(i + 1, col + 1).setValue(fields[f]);
    });
    invalidate(name);
    return;
  }
  var obj = {};
  obj[keyField] = key;
  Object.keys(fields).forEach(function (f) { obj[f] = fields[f]; });
  appendRow(name, obj);
}

function getSetting(key) {
  var rows = readTable('Settings').filter(function (r) { return r.Key === key; });
  return rows.length ? String(rows[0].Value) : null;
}

function setSetting(key, value) {
  invalidate('Settings');
  var sh = sheet('Settings');
  var values = sh.getDataRange().getValues();
  for (var i = 1; i < values.length; i++) {
    if (values[i][0] === key) { sh.getRange(i + 1, 2).setValue(value); invalidate('Settings'); return; }
  }
  sh.appendRow([key, value]);
  invalidate('Settings');
}

function auth(name, pin) {
  ensureSetup();
  var g = findGirl(name);
  checkPin('girl:' + String(name).toLowerCase(), !!g && String(g.PIN).trim() === String(pin).trim());
  duelSeen(g.Name);
  return g;
}

function randomPin() { return String(1000 + Math.floor(Math.random() * 9000)); }

// ---------- Date helpers (yyyy-MM-dd strings, Asia/Jerusalem) ----------

function fmt(d) { return Utilities.formatDate(d, TZ, 'yyyy-MM-dd'); }
function today() { return fmt(new Date()); }
function parseDate(s) { var p = s.split('-'); return new Date(Number(p[0]), Number(p[1]) - 1, Number(p[2]), 12); }
function addDays(s, n) { var d = parseDate(s); d.setDate(d.getDate() + n); return fmt(d); }
function daysBetween(a, b) { return Math.round((parseDate(b) - parseDate(a)) / 86400000); }
function weekStart(s) { return addDays(s, -parseDate(s).getDay()); }
function weekDates(s) { var ws = weekStart(s), out = []; for (var i = 0; i < 7; i++) out.push(addDays(ws, i)); return out; }

// ---- src/Push.js ----
// Web Push (VAPID) for reminders on phones that installed the app.
// Apps Script has no ECDSA, so ES256 (P-256) signing is implemented here with BigInt.
// Pushes carry no payload (no encryption needed): the service worker asks apiPushMessage
// what to show. The VAPID key pair is generated once and kept in Script Properties.

var PUSH_TTL = 6 * 3600;

// ---------- P-256 / ES256 ----------

// Created on first use, so the rest of the app keeps working even if BigInt were unavailable.
var EC_MEMO = null;
function ec() { return EC_MEMO || (EC_MEMO = makeCurve()); }

function makeCurve() {
  var B = function (v) { return BigInt(v); };
  var p = B('0xffffffff00000001000000000000000000000000ffffffffffffffffffffffff');
  var n = B('0xffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551');
  var G = [B('0x6b17d1f2e12c4247f8bce6e563a440f277037d812deb33a0f4a13945d898c296'),
           B('0x4fe342e2fe1a7f9b8ee7eb4a7c0f9e162bce33576b315ececbb6406837bf51f5'), B(1)];
  var Z = B(0), ONE = B(1), TWO = B(2), THREE = B(3), FOUR = B(4), EIGHT = B(8);

  function mod(a, m) { var r = a % m; return r < Z ? r + m : r; }
  function inv(a, m) {
    var lm = ONE, hm = Z, low = mod(a, m), high = m;
    while (low > ONE) {
      var r = high / low;
      var nm = hm - lm * r, nw = high - low * r;
      hm = lm; high = low; lm = nm; low = nw;
    }
    return mod(lm, m);
  }
  // Jacobian coordinates, a = -3.
  function dbl(P) {
    if (P[2] === Z || P[1] === Z) return [Z, ONE, Z];
    var delta = mod(P[2] * P[2], p), gamma = mod(P[1] * P[1], p), beta = mod(P[0] * gamma, p);
    var alpha = mod(THREE * (P[0] - delta) * (P[0] + delta), p);
    var X = mod(alpha * alpha - EIGHT * beta, p);
    var Zn = mod((P[1] + P[2]) * (P[1] + P[2]) - gamma - delta, p);
    var Y = mod(alpha * (FOUR * beta - X) - EIGHT * gamma * gamma, p);
    return [X, Y, Zn];
  }
  function add(P, Q) {
    if (P[2] === Z) return Q;
    if (Q[2] === Z) return P;
    var z1z1 = mod(P[2] * P[2], p), z2z2 = mod(Q[2] * Q[2], p);
    var u1 = mod(P[0] * z2z2, p), u2 = mod(Q[0] * z1z1, p);
    var s1 = mod(P[1] * Q[2] * z2z2, p), s2 = mod(Q[1] * P[2] * z1z1, p);
    var h = mod(u2 - u1, p), r = mod(TWO * (s2 - s1), p);
    if (h === Z) return r === Z ? dbl(P) : [Z, ONE, Z];
    var i = mod(FOUR * h * h, p), j = mod(h * i, p), v = mod(u1 * i, p);
    var X = mod(r * r - j - TWO * v, p);
    var Y = mod(r * (v - X) - TWO * s1 * j, p);
    var Zn = mod(((P[2] + Q[2]) * (P[2] + Q[2]) - z1z1 - z2z2) * h, p);
    return [X, Y, Zn];
  }
  function mul(k, P) {
    var R = [Z, ONE, Z];
    var bits = k.toString(2);
    for (var i = 0; i < bits.length; i++) {
      R = dbl(R);
      if (bits[i] === '1') R = add(R, P);
    }
    return R;
  }
  function affine(P) {
    var zi = inv(P[2], p), zi2 = mod(zi * zi, p);
    return [mod(P[0] * zi2, p), mod(P[1] * zi2 * zi, p)];
  }
  function randomScalar() {
    var seed = Utilities.getUuid() + Utilities.getUuid() + Date.now() + Math.random();
    return mod(bytesToBig(sha256(seed)), n - ONE) + ONE;
  }
  return {
    n: n,
    keyPair: function () {
      var d = randomScalar();
      var Q = affine(mul(d, G));
      return { d: d, x: Q[0], y: Q[1] };
    },
    // Returns r||s (64 bytes) for SHA-256 of msg.
    sign: function (msg, d) {
      var z = bytesToBig(sha256(msg));
      for (;;) {
        var k = randomScalar();
        var r = mod(affine(mul(k, G))[0], n);
        if (r === Z) continue;
        var s = mod(inv(k, n) * (z + r * d), n);
        if (s === Z) continue;
        return bigToBytes(r, 32).concat(bigToBytes(s, 32));
      }
    }
  };
}

function sha256(str) { return Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, str, Utilities.Charset.UTF_8); }
function bytesToBig(bytes) {
  var hex = bytes.map(function (b) { return ('0' + (b & 255).toString(16)).slice(-2); }).join('');
  return BigInt('0x' + (hex || '0'));
}
function bigToBytes(v, len) {
  var hex = v.toString(16);
  while (hex.length < len * 2) hex = '0' + hex;
  var out = [];
  for (var i = 0; i < len; i++) out.push(parseInt(hex.substr(i * 2, 2), 16));
  return out;
}
function b64url(bytesOrString) {
  var s = typeof bytesOrString === 'string'
    ? Utilities.base64EncodeWebSafe(bytesOrString, Utilities.Charset.UTF_8)
    : Utilities.base64EncodeWebSafe(bytesOrString.map(function (b) { return b > 127 ? b - 256 : b; }));
  return s.replace(/=+$/, '');
}

// ---------- VAPID ----------

var VAPID_MEMO = null;

function vapidKeys() {
  if (VAPID_MEMO) return VAPID_MEMO;
  var props = PropertiesService.getScriptProperties();
  var d = props.getProperty('VAPID_D');
  if (!d) {
    var lock = LockService.getScriptLock();
    lock.waitLock(20000);
    try {
      d = props.getProperty('VAPID_D');
      if (!d) {
        var kp = ec().keyPair();
        d = kp.d.toString(16);
        props.setProperties({ VAPID_D: d, VAPID_PUB: b64url([4].concat(bigToBytes(kp.x, 32), bigToBytes(kp.y, 32))) });
      }
    } finally {
      lock.releaseLock();
    }
  }
  VAPID_MEMO = { d: BigInt('0x' + d), pub: props.getProperty('VAPID_PUB') };
  return VAPID_MEMO;
}

function vapidPublicKey() {
  try { return vapidKeys().pub; } catch (e) { return null; }
}

// JWT per push-service origin, reused for 11 hours.
function vapidJwt(endpoint) {
  var aud = endpoint.match(/^https:\/\/[^\/]+/)[0];
  var cache = CacheService.getScriptCache(), key = 'J:' + aud;
  var hit = cache.get(key);
  if (hit) return hit;
  var sub = 'mailto:' + (Session.getEffectiveUser().getEmail() || 'english-quest@example.com');
  var input = b64url(JSON.stringify({ typ: 'JWT', alg: 'ES256' })) + '.' +
    b64url(JSON.stringify({ aud: aud, exp: Math.floor(Date.now() / 1000) + 12 * 3600, sub: sub }));
  var jwt = input + '.' + b64url(ec().sign(input, vapidKeys().d));
  cache.put(key, jwt, 11 * 3600);
  return jwt;
}

// Sends empty pushes in parallel; returns the HTTP statuses (201 ok, 404/410 = subscription gone).
function sendPushes(endpoints) {
  var k = vapidKeys().pub;
  return UrlFetchApp.fetchAll(endpoints.map(function (e) {
    return {
      url: e, method: 'post', payload: '', muteHttpExceptions: true,
      headers: { TTL: String(PUSH_TTL), Urgency: 'normal', Authorization: 'vapid t=' + vapidJwt(e) + ', k=' + k }
    };
  })).map(function (r) { return r.getResponseCode(); });
}

// ---------- Subscriptions & messages ----------

function endpointKey(endpoint) { return 'PM:' + b64url(sha256(endpoint)).slice(0, 40); }

// Notifies a list of devices. Each message waits in the cache for the service worker to
// pick up via apiPushMessage. Dead subscriptions are removed from sheetName.
function deliver(endpoints, message, sheetName) {
  if (!endpoints.length) return { sent: 0, devices: 0 };
  var msgs = {};
  endpoints.forEach(function (e) { msgs[endpointKey(e)] = JSON.stringify(message); });
  CacheService.getScriptCache().putAll(msgs, PUSH_TTL);
  var codes = sendPushes(endpoints), sent = 0, gone = [];
  codes.forEach(function (code, i) {
    if (code === 404 || code === 410) gone.push(endpoints[i]);
    else if (code >= 200 && code < 300) sent++;
    else console.warn('push ' + code + ' to ' + endpoints[i].slice(0, 40));
  });
  if (gone.length) removeSubscriptions(gone, sheetName);
  return { sent: sent, devices: endpoints.length - gone.length };
}

function pushToKid(name, message) {
  return deliver(readTable('Push').filter(function (s) { return s.Girl === name; }).map(function (s) { return s.Endpoint; }), message, 'Push');
}

function removeSubscriptions(endpoints, sheetName) {
  sheetName = sheetName || 'Push';
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    var sh = sheet(sheetName);
    var values = sh.getDataRange().getValues();
    var col = values[0].indexOf('Endpoint');
    for (var i = values.length - 1; i >= 1; i--) {
      if (endpoints.indexOf(String(values[i][col])) >= 0) sh.deleteRow(i + 1);
    }
    invalidate(sheetName);
  } finally {
    lock.releaseLock();
  }
}

// ---------- Parent notifications ----------
// ParentPush rows: Who = 'admin' (every group) or a group id; Instant = 'yes' / 'no'.

function parentDevices(groupId) {
  return readTable('ParentPush').filter(function (r) { return r.Who === 'admin' || r.Who === groupId; });
}

// Parents' phones that want an update as soon as this kid does something.
function instantDevices(kid) {
  return parentDevices(groupOf(kid)).filter(function (r) { return r.Instant !== 'no'; }).map(function (r) { return r.Endpoint; });
}

// Instant update to the kid's parents after she logs a task.
function notifyCompletion(kid, entry) {
  var endpoints = instantDevices(kid);
  if (!endpoints.length) return;
  var msg = entry.Section === 'level'
    ? { title: kid.Name + ' finished the level test', body: 'Level ' + (LEVEL_LABEL[entry.Level] || '?') + ' · +' + entry.Points + ' pts' }
    : { title: kid.Name + ' finished ' + SECTIONS[entry.Section].label,
        body: entry.Title + ' — ' + entry.Correct + '/' + entry.Total + ' (' + entry.Percent + '%) · +' + entry.Points + ' pts' +
          (entry.Date !== entry.DoneOn ? ' · catch-up' : '') };
  deliver(endpoints, msg, 'ParentPush');
}

// Instant update after a gate challenge: the new level, or how close she got.
function notifyGate(kid, row) {
  var endpoints = instantDevices(kid);
  if (!endpoints.length) return;
  var to = LEVEL_LABEL[row.To];
  var msg = row.Passed === 'yes'
    ? { title: kid.Name + ' reached level ' + to + '!',
        body: 'Passed the gate challenge ' + row.Correct + '/' + row.Total + ' · World ' + (LEVELS.indexOf(row.To) + 1) + ', ' + WORLDS[row.To] + ', is open' }
    : { title: kid.Name + ' tried the gate to level ' + to,
        body: row.Correct + '/' + row.Total + ' (' + gateNeed() + ' to pass) · the next try opens in ' + JOURNEY.waitDays + ' days' };
  deliver(endpoints, msg, 'ParentPush');
}

// Time-driven (21:00): who practiced today, per parent.
function parentSummary() {
  var t = today();
  var done = {}, played = {}, gated = {}, duels = {};
  readTable('Log').forEach(function (l) { if (l.Date === t) done[l.Girl] = l; });
  readTable('Games').forEach(function (g) {
    if (g.Date !== t || !(Number(g.Total) > 0)) return;
    if (DUEL_TOGETHER.indexOf(g.Game) >= 0) duels[g.Girl] = (duels[g.Girl] || 0) + 1; else played[g.Girl] = (played[g.Girl] || 0) + 1;
  });
  readTable('Gates').forEach(function (g) { if (g.Date === t) gated[g.Girl] = g; });
  var byWho = {};
  readTable('ParentPush').forEach(function (r) { (byWho[r.Who] = byWho[r.Who] || []).push(r.Endpoint); });
  Object.keys(byWho).forEach(function (who) {
    var kids = who === 'admin' ? readTable('Girls') : kidsIn(who);
    if (!kids.length) return;
    var n = kids.filter(function (k) { return done[k.Name]; }).length;
    var body = kids.map(function (k) {
      var l = done[k.Name], n = played[k.Name], du = duels[k.Name], g = gated[k.Name];
      var games = (n ? ' +' + n + (n === 1 ? ' game' : ' games') : '') + (du ? ' +' + du + (du === 1 ? ' game together' : ' games together') : '');
      var gate = g ? (g.Passed === 'yes' ? 'reached ' + LEVEL_LABEL[g.To] + '!' : 'gate ' + g.Correct + '/' + g.Total) : '';
      if (!l) return k.Name + ' ' + (gate || '—') + games;
      return k.Name + ' ✓' + (l.Section === 'level' ? ' level test' : (l.Percent !== '' ? ' ' + l.Percent + '%' : '')) + games + (gate ? ' · ' + gate : '');
    }).join(' · ');
    // The dinner question of today's mission (Missions.js): a question in English to ask her at home.
    var asks = kids.map(function (k) {
      var l = done[k.Name], m = l && l.Mission ? missionOf(l.URL) : null;
      return m && m.q ? 'Ask ' + k.Name + ': ' + m.q : '';
    }).filter(Boolean).slice(0, 3);
    if (asks.length) body += '\n' + asks.join('\n');
    try { deliver(byWho[who], { title: 'Today: ' + n + '/' + kids.length + ' practiced', body: body }, 'ParentPush'); } catch (e) { console.error(e); }
  });
}

function parentWho(pin) {
  var a = parentAccess(pin);
  return a.isAdmin ? 'admin' : String(a.group.Id);
}

function validEndpoint(endpoint) {
  endpoint = String(endpoint || '');
  if (!/^https:\/\/[^\s]+$/.test(endpoint) || endpoint.length > 1000) throw new Error('Invalid subscription');
  return endpoint;
}

function findParentDevice(who, endpoint) {
  return readTableUncached('ParentPush').filter(function (r) { return r.Who === who && r.Endpoint === endpoint; })[0];
}

// Sets one column of the ParentPush row(s) matching endpoint.
function setParentDevice(endpoint, field, value) {
  var sh = sheet('ParentPush');
  var values = sh.getDataRange().getValues();
  var ec = values[0].indexOf('Endpoint'), fc = values[0].indexOf(field);
  for (var i = 1; i < values.length; i++) {
    if (String(values[i][ec]) === endpoint) sh.getRange(i + 1, fc + 1).setValue(value);
  }
  invalidate('ParentPush');
}

function apiParentPushSubscribe(pin, endpoint, agent, welcome) {
  ensureSetup();
  var who = parentWho(pin);
  endpoint = validEndpoint(endpoint);
  var instant = 'yes';
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    var row = readTableUncached('ParentPush').filter(function (r) { return r.Endpoint === endpoint; })[0];
    if (row) {
      instant = row.Instant === 'no' ? 'no' : 'yes';
      if (row.Who !== who) setParentDevice(endpoint, 'Who', who);
    } else {
      appendRow('ParentPush', { Who: who, Endpoint: endpoint, Created: today(), Agent: String(agent || '').slice(0, 120), Instant: 'yes' });
      audit(who === 'admin' ? 'admin' : 'parent', who === 'admin' ? 'admin' : (findGroup(who) || {}).Name, who === 'admin' ? '' : who, 'notifications on', '');
    }
  } finally {
    lock.releaseLock();
  }
  var res = { instant: instant === 'yes' };
  if (welcome) {
    res.sent = deliver([endpoint], {
      title: 'Parent notifications are on',
      body: 'Daily summary at ' + (Number(getSetting('ParentSummaryHour')) || 21) + ':00' + (res.instant ? ', plus an update whenever a task is done.' : '.')
    }, 'ParentPush').sent;
  }
  return res;
}

function apiParentPushPrefs(pin, endpoint, instant) {
  ensureSetup();
  var who = parentWho(pin);
  endpoint = validEndpoint(endpoint);
  if (!findParentDevice(who, endpoint)) throw new Error('Turn on notifications first');
  setParentDevice(endpoint, 'Instant', instant ? 'yes' : 'no');
  return { instant: !!instant };
}

function apiParentPushTest(pin, endpoint) {
  ensureSetup();
  var who = parentWho(pin);
  endpoint = validEndpoint(endpoint);
  if (!findParentDevice(who, endpoint)) throw new Error('Turn on notifications first');
  return deliver([endpoint], { title: 'Test notification', body: 'Parent notifications are working.' }, 'ParentPush');
}

function reminderMessage(kid, lastCall) {
  var t = today();
  var a = todayTask(kid);
  var logs = readTable('Log').filter(function (l) { return l.Girl === kid.Name; });
  var label = SECTIONS[a.section].label;
  // A duo partner who already practiced today is the best reason to come (Duos.js).
  var duo = null;
  try { duo = duoReminder(kid); } catch (e) { console.error(e); }
  if (duo && lastCall) return { title: 'Last call, ' + kid.Name, body: duo.partner + ' practiced today. ' + (duo.days ? 'Save your ' + duo.days + '-day duo streak: ' : '') + label + ' — ' + a.title };
  if (duo) return { title: duo.partner + ' is waiting for you', body: duo.partner + ' practiced today. ' + (duo.days ? 'Keep your ' + duo.days + '-day duo streak going! ' : '') + 'Today: ' + label };
  if (lastCall) {
    return { title: 'Last call, ' + kid.Name, body: '10 minutes before the day ends — ' + label + ': ' + a.title };
  }
  var s = streak(logs, t, hasShield(kid.Name));
  return {
    title: kid.Name + ', time for English',
    body: 'Today: ' + label + ' — ' + a.title + (s >= 2 ? ' · keep your ' + s + '-day streak going' : '')
  };
}

// Time-driven: push to kids who haven't practiced today.
function pushReminders(lastCall) {
  var t = today();
  var logs = readTable('Log');
  var withDevices = {};
  readTable('Push').forEach(function (s) { withDevices[s.Girl] = true; });
  readTable('Girls').forEach(function (k) {
    if (!withDevices[k.Name]) return;
    if (logs.some(function (l) { return l.Girl === k.Name && l.Date === t; })) return;
    try { pushToKid(k.Name, reminderMessage(k, lastCall)); } catch (e) { console.error(e); }
  });
}

function lastCallReminder() { pushReminders(true); }

// ---------- API ----------

function apiPushSubscribe(name, pin, endpoint, agent, welcome) {
  var kid = auth(name, pin);
  endpoint = validEndpoint(endpoint);
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    // One row per device; a shared device moves to whoever subscribed last.
    var sh = sheet('Push');
    var values = sh.getDataRange().getValues();
    var ec = values[0].indexOf('Endpoint'), gc = values[0].indexOf('Girl'), found = false;
    for (var i = 1; i < values.length; i++) {
      if (String(values[i][ec]) !== endpoint) continue;
      found = true;
      if (values[i][gc] !== kid.Name) sh.getRange(i + 1, gc + 1).setValue(kid.Name);
    }
    if (found) invalidate('Push');
    else {
      appendRow('Push', { Girl: kid.Name, Endpoint: endpoint, Created: today(), Agent: String(agent || '').slice(0, 120) });
      audit('kid', kid.Name, groupOf(kid), 'reminders on', '');
    }
  } finally {
    lock.releaseLock();
  }
  var res = { devices: readTable('Push').filter(function (s) { return s.Girl === kid.Name; }).length };
  if (welcome) {
    res.sent = pushToKid(kid.Name, {
      title: 'Reminders are on',
      body: 'We\'ll remind you at ' + (Number(getSetting('ReminderHour')) || 17) + ':00 on days you haven\'t practiced yet.'
    }).sent;
  }
  return res;
}

// Called by the service worker when a push arrives.
function apiPushMessage(endpoint) {
  var hit = CacheService.getScriptCache().get(endpointKey(String(endpoint || '')));
  return hit ? JSON.parse(hit) : { title: 'English with Coco', body: 'Your 10 minutes of English are waiting.' };
}

function apiAdminTestPush(pin, name) {
  ensureSetup();
  if (!parentAccess(pin).isAdmin) throw new Error('Only the admin can send test reminders');
  var kid = findGirl(name);
  if (!kid) throw new Error('Unknown kid');
  audit('admin', 'admin', groupOf(kid), 'test reminder', kid.Name);
  return pushToKid(kid.Name, { title: 'Test reminder', body: 'Hi ' + kid.Name + ', notifications are working.' });
}

// Run once from the Apps Script editor to grant the "connect to an external service"
// permission that sending notifications needs (web requests can't show the consent screen).
function authorizeNotifications() {
  UrlFetchApp.fetch('https://www.google.com', { muteHttpExceptions: true });
  return 'Notifications are authorized';
}

// ---- src/Duels.js ----
// Play together: Word Duel (live), Challenge (one plays now, the other later), Boss Battle (both against a
// boss) and Talk & Tap (one describes, the other picks), plus the saves of Tug of War (one phone).
// Specs: specs/play-together.md, specs/boss-tug.md, specs/talk-tap.md
// Only functions and literal constants here: files load in one global scope, so nothing at the top
// level may use another file's names.

var DUEL = {
  items: 7, maxMs: 180000, countdownMs: 6000, inviteMin: 5, waitMin: 5, challengeHours: 24,
  winXp: 5, togetherXp: 10, rightXp: 2, onlineMs: 90000, cacheSec: 1800, leftGraceMs: 20000
};
var DUEL_MODES = ['live', 'challenge', 'boss', 'talk'];
// Boss Battle: hit points and damage rules (sent with the duel, so the app shows the same numbers live).
var BOSS = { hp: 240, items: 12, hit: 12, fast: 6, fastMs: 6000, heal: 5, double: 10, doubleMs: 3000, winXp: 10 };
// Talk & Tap: 8 words and the roles swap every word, so each kid picks 4. A pick is `1:4210:2` (right or
// wrong, ms since the start, the option tapped). 6 right words or more is a team win.
var TALK = { items: 8, picks: 4, maxMs: 360000, winAt: 6, winXp: 10 };
var TALK_PICK = /^[01]:\d{1,6}:[0-3]$/;
// Games rows of the games kids play together (the together bonus is for the first of them in a day).
var DUEL_TOGETHER = ['duel', 'boss', 'tug', 'talk'];
// Tug of War: the phone keeps a signed token for the second kid instead of her PIN (valid 2 days), so a
// save that waits for the internet can still credit her; a save id makes a repeated save count once.
var TUG = { maxAnswers: 40, tokenMs: 2 * 24 * 3600000, saveSec: 2 * 24 * 3600 };
var DUEL_REACTIONS = 6;
var DUEL_LETTERS = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
var DUEL_DONE = ['done', 'declined', 'expired', 'cancelled'];

// ---------- API ----------

function apiDuelHome(name, pin) {
  return duelHome(duelKid(name, pin));
}

// Invite any kid in the app (live or challenge), or open a code invite (guest = '').
function apiDuelInvite(name, pin, guestName, mode) {
  var kid = duelKid(name, pin);
  if (DUEL_MODES.indexOf(mode) < 0) throw new Error('Choose a game');
  var guest = null;
  if (guestName) {
    guest = findGirl(guestName);
    if (!guest) throw new Error('Unknown player');
    if (guest.Name === kid.Name) throw new Error('Invite someone else');
    if (!duelCanMeet(kid, guest)) throw new Error('Playing with other groups is switched off for this group');
    if (pendingLevelTest(guest)) throw new Error(guest.Name + ' takes the level test first');
  }
  var now = Date.now(), d, joined = false;
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    var rows = duelRows();
    // Rematch tapped on both phones: join the invite that is already waiting for me.
    var mine = guest && mode !== 'challenge' ? rows.filter(function (r) {
      return r.State === 'invited' && r.Host === guest.Name && r.Guest === kid.Name && Number(r.Expires) > now;
    }).pop() : null;
    if (mine) {
      d = duelStart(mine, kid, now);
      joined = true;
    } else {
      d = {
        Id: duelCode(rows), Created: new Date(now).toISOString(), Date: today(), Mode: mode,
        State: mode === 'challenge' ? 'solo' : 'invited', Host: kid.Name, Guest: guest ? guest.Name : '',
        HostLevel: kid.Level, GuestLevel: guest ? guest.Level : '', Seed: String(1 + Math.floor(Math.random() * 2147483646)),
        Start: '', Expires: String(now + (mode === 'challenge' ? DUEL.challengeHours * 3600000 : DUEL.inviteMin * 60000)), Reply: ''
      };
      duelSave(d, true);
    }
  } finally {
    lock.releaseLock();
  }
  if (!joined && guest && mode !== 'challenge') {
    try { pushToKid(guest.Name, duelMessage('invite', d)); } catch (e) { console.error(e); }
  }
  return duelView(d, kid.Name);
}

// The guest joins a live invite (the start is set a few seconds ahead so both phones count down
// together), or opens a challenge meant for her (a code challenge becomes hers).
function apiDuelJoin(name, pin, code) {
  var kid = duelKid(name, pin), now = Date.now(), d;
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    d = duelFresh(code);
    if (d.Host === kid.Name) return duelView(d, kid.Name);
    if (d.Guest && d.Guest !== kid.Name) throw new Error('This duel is for ' + d.Guest);
    if (!d.Guest) duelCheckFriends(d, kid);
    duelExpire(d, now);
    // A guest who said 'Not now' can still change her mind while the invite is open.
    if (d.State === 'invited' || (d.State === 'declined' && Number(d.Expires) > now)) d = duelStart(d, kid, now);
    else if (d.State === 'challenge' && !d.Guest) { d.Guest = kid.Name; d.GuestLevel = kid.Level; duelSave(d); }
    else if (d.State === 'solo') throw new Error(d.Host + ' is still playing. Try again in a minute.');
    else if (d.State === 'cancelled') throw new Error('This invite was cancelled');
    else if (d.State === 'declined') throw new Error('This invite has expired');
    else if (d.State === 'expired') throw new Error('This invite has expired');
  } finally {
    lock.releaseLock();
  }
  return duelView(d, kid.Name);
}

function apiDuelReply(name, pin, code, reply) {
  var kid = duelKid(name, pin), d;
  if (reply !== 'wait' && reply !== 'no') throw new Error('Unknown reply');
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    d = duelFresh(code);
    if (d.Guest !== kid.Name) throw new Error('This invite is not for you');
    duelExpire(d, Date.now());
    if (d.State !== 'invited') throw new Error('This invite is no longer open');
    d.Reply = reply;
    if (reply === 'no') d.State = 'declined';
    else d.Expires = String(Math.max(Number(d.Expires), Date.now()) + DUEL.waitMin * 60000);
    duelSave(d);
  } finally {
    lock.releaseLock();
  }
  return duelView(d, kid.Name);
}

function apiDuelCancel(name, pin, code) {
  var kid = duelKid(name, pin), d;
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    d = duelFresh(code);
    if (d.Host !== kid.Name) throw new Error('Only ' + d.Host + ' can cancel this invite');
    if (d.State === 'invited' || d.State === 'solo') { d.State = 'cancelled'; d.Ended = new Date().toISOString(); duelSave(d); }
  } finally {
    lock.releaseLock();
  }
  return duelView(d, kid.Name);
}

// Nobody answered the live invite (or the guest said "Not now"): the host plays it now as a challenge.
function apiDuelSolo(name, pin, code) {
  var kid = duelKid(name, pin), d;
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    d = duelFresh(code);
    if (d.Host !== kid.Name) throw new Error('Only ' + d.Host + ' can do this');
    duelExpire(d, Date.now());
    if (['invited', 'declined', 'expired'].indexOf(d.State) < 0) throw new Error('This duel already started');
    d.Mode = 'challenge'; d.State = 'solo'; d.Reply = '';
    d.Expires = String(Date.now() + DUEL.challengeHours * 3600000);
    duelSave(d);
  } finally {
    lock.releaseLock();
  }
  return duelView(d, kid.Name);
}

// The hot path (about every 2 s during a duel): no sheet access unless the duel times out.
function apiDuelPoll(name, pin, code, progress) {
  var kid = duelKid(name, pin), now = Date.now();
  var d = duelGet(code);
  var role = duelRole(d, kid.Name);
  if (!role) throw new Error('This duel is not yours');
  var p = null, most = Math.max(DUEL.items, BOSS.items, TALK.items);
  if (progress && typeof progress === 'object') {
    p = {
      n: duelInt(progress.n, 0, most), s: duelInt(progress.s, 0, most), ms: duelInt(progress.ms, 0, duelMaxMs(d) + 60000),
      f: !!progress.f, r: progress.r >= 0 && progress.r < DUEL_REACTIONS ? duelInt(progress.r, 0, DUEL_REACTIONS - 1) : -1,
      rt: duelInt(progress.rt, 0, 1e15), dmg: duelInt(progress.dmg, -2000, 2000), hint: duelInt(progress.hint, 0, 1e15)
    };
    if (d.Mode === 'talk') p.p = talkMerge(progress.p, (duelProgress(d.Id, kid.Name) || {}).p);
    CacheService.getScriptCache().put('DP:' + d.Id + ':' + kid.Name, JSON.stringify(p), DUEL.cacheSec);
  }
  if ((d.State === 'playing' && now > Number(d.Start) + duelMaxMs(d) + DUEL.leftGraceMs) ||
      ((d.State === 'invited' || d.State === 'solo' || d.State === 'challenge') && now > Number(d.Expires))) {
    var lock = LockService.getScriptLock();
    lock.waitLock(20000);
    try {
      d = duelFresh(code);
      if (d.State === 'playing') duelTimeout(d, now); else duelExpire(d, now);
    } finally {
      lock.releaseLock();
    }
  }
  var other = role === 'host' ? d.Guest : d.Host;
  var out = duelView(d, kid.Name);
  out.them = other ? duelProgress(d.Id, other) : null;
  out.themOnline = other ? duelOnline([other])[other] : false;
  // A talk game's phone that reloaded takes its picks back from here.
  if (d.Mode === 'talk') out.mine = p || duelProgress(d.Id, kid.Name);
  return out;
}

// One player's final result. The second finisher closes the duel; in a challenge the host
// finishing first opens it for the guest (who gets a notification).
function apiDuelFinish(name, pin, code, result) {
  var kid = duelKid(name, pin), now = Date.now(), d, r, closed = false, opened = false, xp = 0;
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    d = duelFresh(code);
    var role = duelRole(d, kid.Name);
    if (!role) throw new Error('This duel is not yours');
    r = duelResult(result, d.Mode);
    var P = role === 'host' ? 'Host' : 'Guest';
    if (d[P + 'Score'] !== '' && d[P + 'Score'] !== undefined && d[P + 'Score'] !== null) throw new Error('Your result is already saved');
    var ok = (d.State === 'playing') || (d.State === 'solo' && role === 'host') || (d.State === 'challenge' && role === 'guest');
    if (!ok) throw new Error(d.State === 'expired' ? 'This duel has expired' : 'This duel is not open');
    d[P + 'Score'] = r.correct; d[P + 'Ms'] = r.ms; d[P + 'Track'] = r.track;
    if (d.State === 'solo') {
      d.State = 'challenge';
      d.Expires = String(now + DUEL.challengeHours * 3600000);
      opened = true;
    } else if (duelHas(d, 'Host') && duelHas(d, 'Guest')) {
      duelClose(d, now);
      closed = true;
    }
    duelSave(d);
    xp = d.Mode === 'talk' ? talkXp(kid, d, role, r) : duelXp(kid, d, role, r);
    var p = duelProgress(d.Id, kid.Name) || {};
    p.n = r.total; p.s = r.correct; p.ms = r.ms; p.f = true;
    if (d.Mode === 'talk') p.p = r.track;
    CacheService.getScriptCache().put('DP:' + d.Id + ':' + kid.Name, JSON.stringify(p), DUEL.cacheSec);
  } finally {
    lock.releaseLock();
  }
  try {
    if (opened && d.Guest) pushToKid(d.Guest, duelMessage('challenge', d));
    if (closed && d.Mode === 'challenge') pushToKid(d.Host, duelMessage('played', d));
  } catch (e) { console.error(e); }
  try { duoAfterPractice(kid.Name); } catch (e) { console.error(e); }
  var out = duelView(d, kid.Name);
  out.xp = xp;
  out.dash = buildDashboard(findGirl(kid.Name));
  return out;
}

// The stronger player explained one of her partner's misses: one Helper star (once per item).
function apiDuelHelped(name, pin, code, itemId) {
  var kid = duelKid(name, pin), d;
  itemId = cleanIds([itemId], 1)[0];
  if (!itemId) throw new Error('Unknown question');
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    d = duelFresh(code);
    if (!duelRole(d, kid.Name)) throw new Error('This duel is not yours');
    if (d.State !== 'done') throw new Error('Finish the duel first');
    var list = String(d.Helped || '').split(' ').filter(String), entry = kid.Name + ':' + itemId;
    if (list.indexOf(entry) < 0 && list.length < 20) { list.push(entry); d.Helped = list.join(' '); duelSave(d); }
  } finally {
    lock.releaseLock();
  }
  var out = duelView(d, kid.Name);
  out.helper = duelHelperStars(kid.Name);
  return out;
}

// ---------- Rules ----------

function duelKid(name, pin) {
  var kid = auth(name, pin);
  if (pendingLevelTest(kid)) throw new Error('Take the level test first.');
  return kid;
}

function duelStart(d, kid, now) {
  d.Guest = kid.Name; d.GuestLevel = kid.Level;
  d.State = 'playing'; d.Start = String(now + DUEL.countdownMs); d.Reply = '';
  duelSave(d);
  return d;
}

// Kids from different groups can play together unless either group switched it off (Groups.Friends = no).
function duelGroupOpen(id) {
  var g = findGroup(id);
  return !(g && String(g.Friends || '').trim().toLowerCase() === 'no');
}
function duelCanMeet(a, b) {
  // Coco's Nest kids (ages 2 to 7) play alone: they never show up in Play together or duo lists.
  if (isNest(a) || isNest(b)) return false;
  return groupOf(a) === groupOf(b) || (duelGroupOpen(groupOf(a)) && duelGroupOpen(groupOf(b)));
}
function duelCheckFriends(d, kid) {
  var host = findGirl(d.Host);
  if (host && !duelCanMeet(host, kid)) throw new Error('Playing with other groups is switched off for this group');
}

// Everyone this kid may play with: her group first, then the other groups (unless switched off).
function duelPlayers(kid) {
  var mine = groupOf(kid);
  return readTable('Girls').filter(function (k) { return k.Name !== kid.Name && duelCanMeet(kid, k); })
    .sort(function (a, b) { return (groupOf(a) === mine ? 0 : 1) - (groupOf(b) === mine ? 0 : 1); });
}

// Lazily closes invites and challenges whose time is up (called inside the lock).
function duelExpire(d, now) {
  if ((d.State === 'invited' || d.State === 'solo' || d.State === 'challenge') && now > Number(d.Expires)) {
    d.State = 'expired';
    d.Ended = new Date(now).toISOString();
    duelSave(d);
  }
}

// A live duel past its time: whoever finished wins; nobody finished -> expired.
function duelTimeout(d, now) {
  var h = duelHas(d, 'Host'), g = duelHas(d, 'Guest');
  if ((h && g) || ((d.Mode === 'boss' || d.Mode === 'talk') && (h || g))) duelClose(d, now);
  else if (h || g) { d.State = 'done'; d.Winner = h ? d.Host : d.Guest; d.Ended = new Date(now).toISOString(); duelBonus(d); }
  else { d.State = 'expired'; d.Ended = new Date(now).toISOString(); }
  duelSave(d);
}

function duelClose(d, now) {
  var hs = Number(d.HostScore), gs = Number(d.GuestScore), hm = Number(d.HostMs), gm = Number(d.GuestMs);
  if (d.Mode === 'boss') d.Winner = bossDamage(d).total >= BOSS.hp ? 'team' : 'boss';
  else if (d.Mode === 'talk') d.Winner = talkTeam(d) >= TALK.winAt ? 'team' : 'none';
  else d.Winner = hs > gs ? d.Host : gs > hs ? d.Guest : hm < gm ? d.Host : gm < hm ? d.Guest : 'draw';
  d.State = 'done';
  d.Ended = new Date(now).toISOString();
  duelBonus(d);
}

// The winner's +5 is a separate zero-question Games row (each player's row is written when she
// finishes, before the winner is known). It still counts inside the daily cap.
function duelBonus(d) {
  if (d.Mode === 'talk') return;
  if (d.Mode === 'boss') {
    if (d.Winner !== 'team') return;
    [d.Host, d.Guest].forEach(function (n) { var k = n && findGirl(n); if (k) duelAddXp(k, BOSS.winXp, 0, 0, '', k.Level, 'boss'); });
    return;
  }
  if (!d.Winner || d.Winner === 'draw') return;
  var w = findGirl(d.Winner);
  if (!w) return;
  duelAddXp(w, DUEL.winXp, 0, 0, '', w.Level);
}

function duelXp(kid, d, role, r) {
  var t = today();
  var together = !readTableUncached('Games').some(function (g) { return g.Girl === kid.Name && g.Date === t && DUEL_TOGETHER.indexOf(g.Game) >= 0 && Number(g.Total) > 0; });
  var xp = r.correct * DUEL.rightXp + (together ? DUEL.togetherXp : 0);
  var got = duelAddXp(kid, xp, r.correct, r.total, r.missed.join(' '), role === 'host' ? d.HostLevel : d.GuestLevel, d.Mode === 'boss' ? 'boss' : 'duel');
  updateReview(kid.Name, r.missed, r.right, t);
  return got;
}

// One Games row (Game = duel, boss or tug), capped like the mini-games. Returns the XP actually given.
function duelAddXp(kid, xp, correct, total, missed, level, game) {
  var t = today();
  var used = readTableUncached('Games').filter(function (g) { return g.Girl === kid.Name && g.Date === t; })
    .reduce(function (a, g) { return a + (Number(g.XP) || 0); }, 0);
  xp = Math.max(0, Math.min(xp, GAME_XP.dayCap - used));
  if (!total && !xp) return 0;
  appendRow('Games', { Timestamp: new Date(), Girl: kid.Name, Date: t, Game: game || 'duel', Level: LEVELS.indexOf(level) >= 0 ? level : kid.Level,
    Correct: correct, Total: total, XP: xp, Missed: missed });
  return xp;
}

// A Word Duel result has all 7 questions (unanswered as '-'); a boss battle has the ones answered (0-12);
// a Talk & Tap result has the kid's own picks (0-4).
function duelResult(res, mode) {
  res = res || {};
  var boss = mode === 'boss', talk = mode === 'talk', max = talk ? TALK.picks : boss ? BOSS.items : DUEL.items;
  var total = duelInt(res.total, 0, max), correct = duelInt(res.correct, 0, total);
  if (!boss && !talk && total !== DUEL.items) throw new Error('Invalid result');
  var track = String(res.track || '').split(',').filter(String), entry = talk ? TALK_PICK : boss ? /^[01]:\d{1,6}$/ : /^[01-]:\d{1,6}$/;
  if (track.length !== total || !track.every(function (x) { return entry.test(x); })) throw new Error('Invalid result');
  if (track.filter(function (x) { return x[0] === '1'; }).length !== correct) throw new Error('Invalid result');
  return { correct: correct, total: total, ms: duelInt(res.ms, 0, (talk ? TALK.maxMs : DUEL.maxMs) + 60000), track: track.join(','),
    missed: cleanIds(res.missed, max), right: cleanIds(res.right, max) };
}

// Boss damage from both tracks in time order: a right answer hits for 12, +6 within 6 s of the kid's
// previous answer (or the start), +10 within 3 s of the partner's right answer; a wrong one heals 5.
function bossDamage(d) {
  var events = [];
  ['Host', 'Guest'].forEach(function (P) {
    var prev = 0;
    String(d[P + 'Track'] || '').split(',').filter(String).forEach(function (x) {
      var p = x.split(':'), t = Number(p[1]) || 0;
      events.push({ who: P, ok: p[0] === '1', t: t, prev: prev });
      prev = t;
    });
  });
  events.sort(function (a, b) { return a.t - b.t; });
  var last = { Host: -1e9, Guest: -1e9 }, dmg = { Host: 0, Guest: 0 };
  events.forEach(function (e) {
    if (!e.ok) { dmg[e.who] -= BOSS.heal; return; }
    var hit = BOSS.hit + (e.t - e.prev <= BOSS.fastMs ? BOSS.fast : 0);
    if (e.t - last[e.who === 'Host' ? 'Guest' : 'Host'] <= BOSS.doubleMs) hit += BOSS.double;
    last[e.who] = e.t;
    dmg[e.who] += hit;
  });
  return { host: dmg.Host, guest: dmg.Guest, total: dmg.Host + dmg.Guest };
}

// ---------- Talk & Tap ----------

// A kid's picks (validated). A phone that reloaded may send fewer: a shorter list never replaces a longer
// one that it is the start of.
function talkMerge(s, old) {
  var list = talkList(s), prev = talkList(old);
  if (prev.length > list.length && prev.slice(0, list.length).join(',') === list.join(',')) return prev.join(',');
  return list.join(',');
}

function talkList(s) {
  var list = String(s || '').split(',').filter(String);
  return list.length <= TALK.picks && list.every(function (x) { return TALK_PICK.test(x); }) ? list : [];
}

function talkTeam(d) { return (Number(d.HostScore) || 0) + (Number(d.GuestScore) || 0); }

// Every word the team got right counts for both kids: one described it, the other picked it. The
// partner's picks come from her saved result, or from her last poll if she has not finished yet. The
// together bonus needs a pick of her own (stopping at once and starting again earns nothing extra).
function talkXp(kid, d, role, r) {
  var t = today(), P = role === 'host' ? 'Guest' : 'Host';
  var mate = duelHas(d, P) ? Number(d[P + 'Score']) || 0
    : talkList((duelProgress(d.Id, d[P]) || {}).p).filter(function (x) { return x[0] === '1'; }).length;
  var team = r.correct + mate;
  var together = r.total > 0 && !readTableUncached('Games').some(function (g) { return g.Girl === kid.Name && g.Date === t && DUEL_TOGETHER.indexOf(g.Game) >= 0 && Number(g.Total) > 0; });
  var xp = team * DUEL.rightXp + (together ? DUEL.togetherXp : 0) + (team >= TALK.winAt ? TALK.winXp : 0);
  var got = duelAddXp(kid, xp, r.correct, r.total, r.missed.join(' '), role === 'host' ? d.HostLevel : d.GuestLevel, 'talk');
  updateReview(kid.Name, r.missed, r.right, t);
  return got;
}

// ---------- Tug of War (one phone) ----------

// The second kid on the same phone proves who she is with her PIN, once; the phone gets a token for the save.
function apiTugCheck(name, pin) {
  var kid = duelKid(name, pin), p = petInfo(kid);
  return { name: kid.Name, level: kid.Level, label: LEVEL_LABEL[kid.Level] || kid.Level, color: kid.Color, pet: petBrief(p),
    token: tugToken(kid) };
}

function tugSecret() {
  var props = PropertiesService.getScriptProperties(), s = props.getProperty('TugSecret');
  if (!s) { s = Utilities.getUuid(); props.setProperty('TugSecret', s); }
  return s;
}
function tugSign(name, exp) {
  return Utilities.base64EncodeWebSafe(Utilities.computeHmacSha256Signature(String(name).toLowerCase() + '|' + exp, tugSecret())).slice(0, 22);
}
function tugToken(kid) {
  var exp = Date.now() + TUG.tokenMs;
  return exp + '.' + tugSign(kid.Name, exp);
}
// The second kid: her PIN, or the token from apiTugCheck (a token has a dot, a PIN never does).
function tugMate(name, cred) {
  cred = String(cred || '');
  if (cred.indexOf('.') < 0) return duelKid(name, cred);
  var parts = cred.split('.'), exp = Number(parts[0]), kid = findGirl(name);
  if (!kid || !(exp > Date.now()) || parts[1] !== tugSign(kid.Name, exp)) throw new Error('Wrong PIN');
  if (pendingLevelTest(kid)) throw new Error('Take the level test first.');
  return kid;
}

// Both results at once ({correct, total, missed, right}); mate = '' plays as a guest and saves nothing.
// mateCred is her PIN or her token; saveId (from the phone) makes a save that is sent again count once.
function apiTugSave(name, pin, mateName, mateCred, mine, hers, saveId) {
  var kid = duelKid(name, pin), mate = mateName ? tugMate(mateName, mateCred) : null, xp = {}, t = today();
  var sid = /^[A-Za-z0-9-]{8,40}$/.test(String(saveId || '')) ? 'TS:' + saveId : '', cache = CacheService.getScriptCache();
  if (mate && mate.Name === kid.Name) throw new Error('Two different players, please');
  var players = [[kid, tugResult(mine)]].concat(mate ? [[mate, tugResult(hers)]] : []);
  var lock = LockService.getScriptLock(), seen = null;
  lock.waitLock(20000);
  try {
    seen = sid ? cache.get(sid) : null;
    if (!seen) players.forEach(function (p) {
      var k = p[0], r = p[1];
      if (!r.total) return;
      var together = mate && !readTableUncached('Games').some(function (g) { return g.Girl === k.Name && g.Date === t && DUEL_TOGETHER.indexOf(g.Game) >= 0 && Number(g.Total) > 0; });
      xp[k.Name] = duelAddXp(k, r.correct * DUEL.rightXp + (together ? DUEL.togetherXp : 0), r.correct, r.total, r.missed.join(' '), k.Level, 'tug');
      updateReview(k.Name, r.missed, r.right, t);
    });
    if (sid && !seen) cache.put(sid, JSON.stringify({ xp: xp[kid.Name] || 0, mateXp: mate ? xp[mate.Name] || 0 : null }), TUG.saveSec);
  } finally {
    lock.releaseLock();
  }
  if (seen) { var was = JSON.parse(seen); return { xp: was.xp, mateXp: was.mateXp, again: true, dash: buildDashboard(findGirl(kid.Name)) }; }
  players.forEach(function (p) { try { duoAfterPractice(p[0].Name); } catch (e) { console.error(e); } });
  return { xp: xp[kid.Name] || 0, mateXp: mate ? xp[mate.Name] || 0 : null, dash: buildDashboard(findGirl(kid.Name)) };
}

function tugResult(res) {
  res = res || {};
  var total = duelInt(res.total, 0, TUG.maxAnswers), correct = duelInt(res.correct, 0, total);
  return { correct: correct, total: total, missed: cleanIds(res.missed, TUG.maxAnswers), right: cleanIds(res.right, TUG.maxAnswers) };
}

// ---------- Views ----------

function duelHome(kid) {
  var now = Date.now(), t = today(), name = kid.Name;
  var rows = readTable('Duels');
  var mates = duelPlayers(kid), mine = groupOf(kid);
  var online = duelOnline(mates.map(function (k) { return k.Name; }));
  var live = function (r) { return Number(r.Expires) > now; };
  var withMe = rows.filter(function (r) { return r.Host === name || r.Guest === name; });
  return {
    friends: mates.map(function (k) {
      var pet = petInfo(k);
      var g = findGroup(groupOf(k));
      return { name: k.Name, color: k.Color, level: LEVEL_LABEL[k.Level] || k.Level, ready: !pendingLevelTest(k), online: !!online[k.Name],
        group: groupOf(k) === mine ? '' : (g ? String(g.Name) : ''),
        pet: petBrief(pet) };
    }),
    incoming: withMe.filter(function (r) { return r.State === 'invited' && r.Guest === name && live(r); }).map(function (r) { return duelView(r, name); }),
    challenges: withMe.filter(function (r) { return r.State === 'challenge' && r.Guest === name && live(r); }).map(function (r) { return duelView(r, name); }),
    waiting: withMe.filter(function (r) { return r.Host === name && (r.State === 'challenge' || r.State === 'invited') && live(r); }).map(function (r) { return duelView(r, name); }),
    results: withMe.filter(function (r) { return r.State === 'done' && r.Date >= addDays(t, -7); }).slice(-5).reverse().map(function (r) { return duelView(r, name); }),
    // A live game still running that she has not finished (after a reload or a call): the app offers to go back.
    playing: withMe.filter(function (r) { return r.State === 'playing' && Number(r.Start) + duelMaxMs(r) > now && !duelHas(r, r.Host === name ? 'Host' : 'Guest'); })
      .map(function (r) { return duelView(r, name); }),
    helper: duelHelperStars(name),
    duos: duoHome(kid),
    now: now
  };
}

// What a player may see of a duel. Tracks are shown once both played (or to their owner), so a
// challenge can't be peeked at before playing it... except the host's track, which is the ghost.
function duelView(d, me) {
  var role = duelRole(d, me), host = findGirl(d.Host), guest = d.Guest ? findGirl(d.Guest) : null;
  var face = function (k) { return petBrief(k ? petInfo(k) : null); };
  var done = d.State === 'done';
  var v = {
    code: d.Id, mode: d.Mode, state: d.State, role: role, seed: Number(d.Seed),
    items: d.Mode === 'boss' ? BOSS.items : d.Mode === 'talk' ? TALK.items : DUEL.items, maxMs: duelMaxMs(d),
    start: d.Start ? Number(d.Start) : null, expires: Number(d.Expires) || null, reply: d.Reply || '', now: Date.now(), date: d.Date,
    host: { name: d.Host, level: d.HostLevel, label: LEVEL_LABEL[d.HostLevel] || '', color: host ? host.Color : '', pet: face(host),
      score: duelHas(d, 'Host') ? Number(d.HostScore) : null, ms: duelHas(d, 'Host') ? Number(d.HostMs) : null },
    guest: d.Guest ? { name: d.Guest, level: d.GuestLevel, label: LEVEL_LABEL[d.GuestLevel] || '', color: guest ? guest.Color : '', pet: face(guest),
      score: duelHas(d, 'Guest') ? Number(d.GuestScore) : null, ms: duelHas(d, 'Guest') ? Number(d.GuestMs) : null } : null,
    winner: d.Winner || '', helped: String(d.Helped || '').split(' ').filter(String)
  };
  if (duelHas(d, 'Host') && (done || d.Mode === 'challenge' || role === 'host')) v.host.track = String(d.HostTrack);
  if (duelHas(d, 'Guest') && (done || role === 'guest')) v.guest.track = String(d.GuestTrack);
  if (!guest && !d.Guest && d.State !== 'done') v.open = true;
  if (d.Mode === 'boss') { v.boss = BOSS; if (done) v.damage = bossDamage(d); }
  if (d.Mode === 'talk') { v.talk = TALK; if (done) v.team = talkTeam(d); }
  return v;
}

function duelHelperStars(name) {
  var n = 0;
  readTable('Duels').forEach(function (r) {
    String(r.Helped || '').split(' ').forEach(function (e) { if (e.indexOf(name + ':') === 0) n++; });
  });
  return n;
}

// ---------- Storage ----------

function duelRows() { return readTableUncached('Duels'); }

function duelCode(rows) {
  var used = {};
  rows.forEach(function (r) { used[r.Id] = true; });
  for (var tries = 0; tries < 200; tries++) {
    var c = '';
    for (var i = 0; i < 4; i++) c += DUEL_LETTERS[Math.floor(Math.random() * DUEL_LETTERS.length)];
    if (!used[c]) return c;
  }
  throw new Error('Could not create a code, try again');
}

function duelNorm(code) {
  code = String(code || '').toUpperCase().replace(/[^A-Z]/g, '');
  if (code.length !== 4) throw new Error('A code has 4 letters');
  return code;
}

// From the cache (fast path for polls), else the sheet.
function duelGet(code) {
  code = duelNorm(code);
  var hit = CacheService.getScriptCache().get('DM:' + code);
  if (hit) return JSON.parse(hit);
  return duelFresh(code);
}

// Straight from the sheet (inside the lock for every change).
function duelFresh(code) {
  code = duelNorm(code);
  var d = duelRows().filter(function (r) { return r.Id === code; })[0];
  if (!d) throw new Error('No duel with the code ' + code);
  duelCache(d);
  return d;
}

function duelCache(d) {
  try { CacheService.getScriptCache().put('DM:' + d.Id, JSON.stringify(d), DUEL.cacheSec); } catch (e) {}
}

// Writes the whole row (one sheet call) and refreshes the cache.
function duelSave(d, isNew) {
  var sh = sheet('Duels');
  var head = sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0];
  var row = head.map(function (h) { return d[h] === undefined || d[h] === null ? '' : d[h]; });
  if (isNew) sh.appendRow(row);
  else {
    var ids = sh.getRange(1, head.indexOf('Id') + 1, sh.getLastRow(), 1).getValues();
    var at = -1;
    for (var i = ids.length - 1; i >= 1; i--) { if (String(ids[i][0]).trim() === d.Id) { at = i + 1; break; } }
    if (at < 0) sh.appendRow(row); else sh.getRange(at, 1, 1, head.length).setValues([row]);
  }
  invalidate('Duels');
  duelCache(d);
}

function duelProgress(code, name) {
  var hit = CacheService.getScriptCache().get('DP:' + code + ':' + name);
  return hit ? JSON.parse(hit) : null;
}

function duelOnline(names) {
  var out = {};
  if (!names.length) return out;
  var got = CacheService.getScriptCache().getAll(names.map(function (n) { return 'ON:' + n; }));
  var now = Date.now();
  names.forEach(function (n) { out[n] = Number(got['ON:' + n]) > now - DUEL.onlineMs; });
  return out;
}

function duelSeen(name) {
  try { CacheService.getScriptCache().put('ON:' + name, String(Date.now()), 600); } catch (e) {}
}

function duelRole(d, name) { return d.Host === name ? 'host' : d.Guest === name ? 'guest' : null; }
function duelHas(d, P) { return d[P + 'Score'] !== '' && d[P + 'Score'] !== undefined && d[P + 'Score'] !== null; }
function duelMaxMs(d) { return d.Mode === 'talk' ? TALK.maxMs : DUEL.maxMs; }
function duelInt(v, min, max) { v = Math.round(Number(v)); return isNaN(v) ? min : Math.max(min, Math.min(max, v)); }

// ---------- Notifications ----------

function duelMessage(kind, d) {
  var url = './?duel=' + d.Id, score = function (s, ms) { return s + '/' + DUEL.items + ' in ' + Math.round(ms / 1000) + ' s'; };
  if (kind === 'invite' && d.Mode === 'talk') return { title: d.Host + ' invites you to Talk & Tap', body: 'Describe words in English, together. Tap to join!', url: url, tag: 'eq-duel' };
  if (kind === 'invite' && d.Mode === 'boss') return { title: d.Host + ' invites you to a Boss Battle', body: 'Team up against the Word Thief. Tap to join!', url: url, tag: 'eq-duel' };
  if (kind === 'invite') return { title: d.Host + ' invites you to a Word Duel', body: DUEL.items + ' questions at your level. Tap to join!', url: url, tag: 'eq-duel' };
  if (kind === 'challenge') return { title: d.Host + ' challenged you!', body: 'Beat ' + score(d.HostScore, d.HostMs) + '. You have ' + DUEL.challengeHours + ' hours.', url: url, tag: 'eq-duel' };
  var res = d.Winner === d.Host ? 'You won!' : d.Winner === 'draw' ? 'A draw!' : d.Guest + ' won.';
  return { title: d.Guest + ' played your challenge', body: d.Guest + ' ' + d.GuestScore + '/' + DUEL.items + ' · you ' + d.HostScore + '/' + DUEL.items + '. ' + res + ' Rematch?', url: url, tag: 'eq-duel' };
}

// ---- src/Duos.js ----
// Play together, phase 2: Duo Streak and Team Quest. Spec: specs/duo-streak.md
// Only functions and literal constants here: files load in one global scope, so nothing at the top
// level may use another file's names.

var DUO = {
  max: 4, milestones: [7, 30, 100], milestoneXp: [20, 60, 150],
  questXp: 40, questGameTarget: 40, questDaysTarget: 5, questMinAnswers: 10
};
var DUO_GAMES = ['match', 'listen', 'build', 'spot'];
var DUO_GAME_NAMES = { match: 'Match it', listen: 'Hear it', build: 'Build it', spot: 'Spot it' };
var DUO_MEMO = { log: null, games: null, days: {} };

// ---------- API ----------

// Ask for a duo streak; if she already asked me, this accepts hers.
function apiDuoInvite(name, pin, partnerName) {
  var kid = duelKid(name, pin), mate = findGirl(partnerName), note = null;
  if (!mate) throw new Error('Unknown player');
  if (mate.Name === kid.Name) throw new Error('Choose someone else');
  if (!duelCanMeet(kid, mate)) throw new Error('Playing with other groups is switched off for this group');
  if (pendingLevelTest(mate)) throw new Error(mate.Name + ' takes the level test first');
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    var rows = duoRows();
    var pair = rows.filter(function (r) { return duoHas(r, kid.Name) && duoHas(r, mate.Name) && (r.State === 'active' || r.State === 'invited'); })[0];
    if (pair && pair.State === 'active') throw new Error('You already have a duo streak with ' + mate.Name);
    if (pair && pair.A === kid.Name) throw new Error('You already asked ' + mate.Name + '. Waiting for an answer.');
    if (duoCount(rows, kid.Name) >= DUO.max) throw new Error('You can have up to ' + DUO.max + ' duo streaks');
    if (duoCount(rows, mate.Name) >= DUO.max) throw new Error(mate.Name + ' already has ' + DUO.max + ' duo streaks');
    if (pair) {
      pair.State = 'active'; pair.Since = today();
      duoSave(pair);
      note = { to: mate.Name, msg: duoMessage('yes', kid.Name) };
    } else {
      duoSave({ Id: duoNewId(rows), Created: new Date().toISOString(), A: kid.Name, B: mate.Name, State: 'invited',
        Since: '', Ended: '', Nudges: '', Milestones: '', QuestDone: '' }, true);
      note = { to: mate.Name, msg: duoMessage('ask', kid.Name) };
    }
  } finally {
    lock.releaseLock();
  }
  try { pushToKid(note.to, note.msg); } catch (e) { console.error(e); }
  return duoHome(kid);
}

function apiDuoAnswer(name, pin, id, accept) {
  var kid = duelKid(name, pin), d;
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    d = duoFresh(id);
    if (d.B !== kid.Name) throw new Error('This request is not for you');
    if (d.State !== 'invited') throw new Error('This request is no longer open');
    if (accept) {
      if (duoCount(duoRows(), kid.Name) >= DUO.max) throw new Error('You can have up to ' + DUO.max + ' duo streaks');
      d.State = 'active'; d.Since = today();
    } else {
      d.State = 'declined'; d.Ended = new Date().toISOString();
    }
    duoSave(d);
  } finally {
    lock.releaseLock();
  }
  if (accept) { try { pushToKid(d.A, duoMessage('yes', kid.Name)); } catch (e) { console.error(e); } }
  return duoHome(kid);
}

// A friendly reminder to a partner who hasn't practiced today (once a day per kid per duo).
function apiDuoNudge(name, pin, id) {
  var kid = duelKid(name, pin), t = today(), d, other, s;
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    d = duoFresh(id);
    if (!duoHas(d, kid.Name) || d.State !== 'active') throw new Error('This duo streak is not active');
    other = duoOther(d, kid.Name);
    if (practiceDays(other)[t]) throw new Error(other + ' already practiced today');
    var nudges = duoNudges(d);
    if (nudges[kid.Name] === t) throw new Error('You already nudged ' + other + ' today');
    nudges[kid.Name] = t;
    d.Nudges = Object.keys(nudges).map(function (k) { return k + ':' + nudges[k]; }).join(' ');
    duoSave(d);
    s = duoStreak(d, t);
  } finally {
    lock.releaseLock();
  }
  var did = !!practiceDays(kid.Name)[t];
  try {
    pushToKid(other, { title: kid.Name + ' is waiting for you', url: './', tag: 'eq-duo',
      body: (did ? kid.Name + ' practiced today. ' : '') + (s.days ? 'Keep your ' + s.days + '-day duo streak going!' : 'Practice today, both of you, and start your duo streak!') });
  } catch (e) { console.error(e); }
  return duoHome(kid);
}

// Either kid can stop a duo streak (or take back a request).
function apiDuoEnd(name, pin, id) {
  var kid = duelKid(name, pin);
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    var d = duoFresh(id);
    if (!duoHas(d, kid.Name)) throw new Error('This duo streak is not yours');
    if (d.State === 'active' || d.State === 'invited') { d.State = 'ended'; d.Ended = new Date().toISOString(); duoSave(d); }
  } finally {
    lock.releaseLock();
  }
  return duoHome(kid);
}

// ---------- Rewards (after every practice) ----------

// Milestones and finished quests give both kids their XP once. Cheap when nothing is due:
// everything is read from the cache first, and the lock is taken only to give a reward.
function duoAfterPractice(name) {
  var t = today();
  var due = readTable('Duos').filter(function (r) { return r.State === 'active' && duoHas(r, name) && duoDue(r, t); });
  if (!due.length) return;
  var notes = [];
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    duoRows().filter(function (r) { return r.State === 'active' && duoHas(r, name); }).forEach(function (d) {
      var s = duoStreak(d, t), q = duoQuest(d, t), reached = duoList(d.Milestones), weeks = duoList(d.QuestDone), changed = false;
      DUO.milestones.forEach(function (m, i) {
        if (s.days < m || reached.indexOf(String(m)) >= 0) return;
        reached.push(String(m)); changed = true;
        duoBonus([d.A, d.B], 'duo-streak', DUO.milestoneXp[i], d.Id + ':' + m);
        notes.push({ to: [d.A, d.B], msg: { title: m + '-day duo streak!', url: './', tag: 'eq-duo',
          body: d.A + ' and ' + d.B + ' practiced together ' + m + ' days in a row. +' + DUO.milestoneXp[i] + ' XP each!' } });
      });
      if (q.done && weeks.indexOf(q.week) < 0) {
        weeks.push(q.week); changed = true;
        duoBonus([d.A, d.B], 'quest', DUO.questXp, d.Id + ':q:' + q.week);
        notes.push({ to: [d.A, d.B], msg: { title: 'Team quest complete!', url: './', tag: 'eq-duo',
          body: d.A + ' and ' + d.B + ' did it: ' + q.goal + '. +' + DUO.questXp + ' XP each!' } });
      }
      if (changed) { d.Milestones = reached.join(' '); d.QuestDone = weeks.slice(-12).join(' '); duoSave(d); }
    });
  } finally {
    lock.releaseLock();
  }
  notes.forEach(function (n) { n.to.forEach(function (k) { try { pushToKid(k, n.msg); } catch (e) { console.error(e); } }); });
}

function duoDue(d, t) {
  var s = duoStreak(d, t), reached = duoList(d.Milestones);
  if (DUO.milestones.some(function (m) { return s.days >= m && reached.indexOf(String(m)) < 0; })) return true;
  var q = duoQuest(d, t);
  return q.done && duoList(d.QuestDone).indexOf(q.week) < 0;
}

// One Bonus row per kid and ref, so an award never repeats.
function duoBonus(names, kind, xp, ref) {
  var rows = readTableUncached('Bonus');
  names.forEach(function (n) {
    if (rows.some(function (b) { return b.Girl === n && b.Ref === ref; })) return;
    appendRow('Bonus', { Timestamp: new Date(), Girl: n, Date: today(), Kind: kind, XP: xp, Ref: ref });
  });
}

// ---------- Streak and quest ----------

// Days with a task logged, or a game or duel round played.
function practiceDays(name) {
  var log = readTable('Log'), games = readTable('Games');
  if (DUO_MEMO.log !== log || DUO_MEMO.games !== games) DUO_MEMO = { log: log, games: games, days: {} };
  if (DUO_MEMO.days[name]) return DUO_MEMO.days[name];
  var days = {};
  log.forEach(function (l) { if (l.Girl === name && l.DoneOn) days[String(l.DoneOn)] = true; });
  games.forEach(function (g) { if (g.Girl === name && Number(g.Total) > 0) days[String(g.Date)] = true; });
  return DUO_MEMO.days[name] = days;
}

// Days since the duo started on which both practiced, counted forward in time so the past never
// changes: the first missed day of a week (Sun-Sat) is forgiven and shown as saved, a second one
// breaks the streak. Today can't break it until it is over.
function duoStreak(d, t) {
  var a = practiceDays(d.A), b = practiceDays(d.B), since = String(d.Since || t);
  var both = function (x) { return !!(a[x] && b[x]); };
  var n = 0, used = {}, saved = [];
  for (var x = since; x <= t; x = addDays(x, 1)) {
    if (both(x)) { n++; continue; }
    if (x === t) break;
    var w = weekStart(x);
    if (n > 0 && !used[w]) { used[w] = true; saved.push(x); continue; }
    n = 0; saved = [];
  }
  return { days: n, both: both(t), saved: saved };
}

// This week's quest, chosen from both kids' games last week: their weakest game type, or (no data)
// practising on the same day. A duo that started this week counts from its first day, with a smaller
// goal. It is a team quest: each kid brings at least a tenth of a game goal.
function duoQuest(d, t) {
  var ws = weekStart(t), last = addDays(ws, -7), names = [d.A, d.B], games = readTable('Games'), acc = {}, had = {};
  var from = d.Since && String(d.Since) > ws ? String(d.Since) : ws;
  var share = (daysBetween(from, addDays(ws, 6)) + 1) / 7;
  games.forEach(function (g) {
    if (names.indexOf(g.Girl) < 0 || DUO_GAMES.indexOf(g.Game) < 0 || !(Number(g.Total) > 0) || g.Date < last || g.Date >= ws) return;
    var s = acc[g.Game] = acc[g.Game] || { c: 0, n: 0 };
    s.c += Number(g.Correct) || 0; s.n += Number(g.Total) || 0;
    had[g.Girl] = true;
  });
  var weak = null;
  DUO_GAMES.forEach(function (k) {
    var s = acc[k];
    if (s && s.n >= DUO.questMinAnswers && (!weak || s.c / s.n < acc[weak].c / acc[weak].n)) weak = k;
  });
  var q;
  if (weak) {
    var target = Math.max(10, Math.round(DUO.questGameTarget * share / 5) * 5), per = {};
    names.forEach(function (n) { per[n] = 0; });
    games.forEach(function (g) {
      if (g.Game === weak && names.indexOf(g.Girl) >= 0 && g.Date >= from && g.Date <= t && Number(g.Total) > 0) per[g.Girl] += Number(g.Correct) || 0;
    });
    q = { kind: 'game', game: weak, title: DUO_GAME_NAMES[weak] + ' together', target: target, minEach: Math.ceil(target / 10),
      goal: target + ' right answers in ' + DUO_GAME_NAMES[weak] + ' as a team', a: per[d.A], b: per[d.B],
      reason: DUO_GAME_NAMES[weak] + ' was the hardest game ' + (had[d.A] && had[d.B] ? 'for you two ' : '') + 'last week (' + Math.round(acc[weak].c / acc[weak].n * 100) + '% right).' };
    q.total = q.a + q.b;
    q.done = q.total >= q.target && q.a >= q.minEach && q.b >= q.minEach;
  } else {
    var A = practiceDays(d.A), B = practiceDays(d.B), goal = Math.max(1, Math.min(DUO.questDaysTarget, Math.round(DUO.questDaysTarget * share)));
    var n = weekDates(t).filter(function (x) { return x >= from && x <= t && A[x] && B[x]; }).length;
    q = { kind: 'days', title: 'Practice buddies', target: goal, minEach: null, goal: 'Practice on the same day ' + (goal === 1 ? 'once' : goal + ' times'),
      a: null, b: null, total: n, reason: 'A habit you build together lasts longer.' };
    q.done = q.total >= q.target;
  }
  q.week = ws;
  q.daysLeft = daysBetween(t, addDays(ws, 6)) + 1;
  q.xp = DUO.questXp;
  return q;
}

// ---------- Views ----------

function duoHome(kid) {
  var t = today(), name = kid.Name;
  var rows = readTable('Duos').filter(function (r) { return duoHas(r, name); });
  var urgent = function (v) { return v.todayMe && v.todayThem ? 2 : v.todayMe || v.todayThem ? 0 : 1; };
  return {
    incoming: rows.filter(function (r) { return r.State === 'invited' && r.B === name; }).map(function (r) { return { id: r.Id, partner: duoPlayer(r.A) }; }),
    outgoing: rows.filter(function (r) { return r.State === 'invited' && r.A === name; }).map(function (r) { return { id: r.Id, partner: duoPlayer(r.B) }; }),
    active: rows.filter(function (r) { return r.State === 'active'; }).map(function (r) { return duoView(r, name, t); })
      .sort(function (a, b) { return urgent(a) - urgent(b) || b.days - a.days; }),
    max: DUO.max, milestones: DUO.milestones, milestoneXp: DUO.milestoneXp
  };
}

function duoView(d, me, t) {
  var other = duoOther(d, me), s = duoStreak(d, t), A = practiceDays(me), B = practiceDays(other), q = duoQuest(d, t);
  var first = d.A === me, reached = duoList(d.Milestones).map(Number);
  return {
    id: d.Id, partner: duoPlayer(other), since: d.Since, days: s.days, todayMe: !!A[t], todayThem: !!B[t],
    week: weekDates(t).map(function (x) { return { date: x, me: !!A[x], them: !!B[x], saved: s.saved.indexOf(x) >= 0, future: x > t, before: x < d.Since }; }),
    milestones: reached, next: DUO.milestones.filter(function (m) { return m > s.days; })[0] || null, nudged: duoNudges(d)[me] === t,
    quest: { kind: q.kind, game: q.game || null, title: q.title, goal: q.goal, target: q.target, total: q.total, reason: q.reason,
      me: q.a === null ? null : (first ? q.a : q.b), them: q.b === null ? null : (first ? q.b : q.a),
      minEach: q.minEach, done: q.done, claimed: duoList(d.QuestDone).indexOf(q.week) >= 0, week: q.week, daysLeft: q.daysLeft, xp: q.xp }
  };
}

function duoPlayer(name) {
  var k = findGirl(name), pet = k ? petInfo(k) : null;
  return { name: name, color: k ? k.Color : '', level: k ? (LEVEL_LABEL[k.Level] || k.Level) : '', pet: petBrief(pet) };
}

// The 17:00 / 20:00 reminder of a kid who hasn't practiced: a partner who already did today.
function duoReminder(kid) {
  var t = today();
  if (practiceDays(kid.Name)[t]) return null;
  var best = null;
  readTable('Duos').forEach(function (d) {
    if (d.State !== 'active' || !duoHas(d, kid.Name)) return;
    var other = duoOther(d, kid.Name);
    if (!practiceDays(other)[t]) return;
    var days = duoStreak(d, t).days;
    if (!best || days > best.days) best = { partner: other, days: days };
  });
  return best;
}

function duoMessage(kind, from) {
  if (kind === 'ask') return { title: from + ' wants a duo streak with you', body: 'Practice on the same days and grow a streak together. Tap to answer.', url: './', tag: 'eq-duo' };
  return { title: from + ' said yes!', body: 'Your duo streak starts today. Practice today, both of you.', url: './', tag: 'eq-duo' };
}

// ---------- Storage ----------

function duoRows() { return readTableUncached('Duos'); }
function duoHas(d, name) { return d.A === name || d.B === name; }
function duoOther(d, name) { return d.A === name ? d.B : d.A; }
function duoList(s) { return String(s || '').split(' ').filter(String); }
function duoCount(rows, name) { return rows.filter(function (r) { return r.State === 'active' && duoHas(r, name); }).length; }
function duoNudges(d) {
  var out = {};
  duoList(d.Nudges).forEach(function (e) { var i = e.lastIndexOf(':'); out[e.slice(0, i)] = e.slice(i + 1); });
  return out;
}

function duoNewId(rows) {
  var used = {};
  rows.forEach(function (r) { used[r.Id] = true; });
  for (;;) {
    var id = 'U' + Math.random().toString(36).slice(2, 8);
    if (!used[id]) return id;
  }
}

function duoFresh(id) {
  var d = duoRows().filter(function (r) { return r.Id === String(id); })[0];
  if (!d) throw new Error('Unknown duo streak');
  return d;
}

// Writes the whole row in one call.
function duoSave(d, isNew) {
  var sh = sheet('Duos');
  var head = sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0];
  var row = head.map(function (h) { return d[h] === undefined || d[h] === null ? '' : d[h]; });
  if (isNew) sh.appendRow(row);
  else {
    var ids = sh.getRange(1, head.indexOf('Id') + 1, sh.getLastRow(), 1).getValues(), at = -1;
    for (var i = ids.length - 1; i >= 1; i--) { if (String(ids[i][0]).trim() === d.Id) { at = i + 1; break; } }
    if (at < 0) sh.appendRow(row); else sh.getRange(at, 1, 1, head.length).setValues([row]);
  }
  invalidate('Duos');
}

