// ---- src/Missions.js ----
// Today's Mission (specs/missions.md): the daily task played in the app, with a measured score.
// The content lives on GitHub Pages (docs/missions/<level>.js); MISSION_INDEX (MissionIndex.js, generated by
// tools/missions-index.js) tells the server which catalog topics have a mission and how many questions it has.

var MISSION = { minSeconds: 30, flagsPerDay: 20 };

// Today's Mission is every kid's daily task; Girls.Missions = no keeps her on the link to test-english.com (the old way).
function missionsOn(kid) {
  return String(kid.Missions || '').trim().toLowerCase() !== 'no';
}

function missionOf(url) {
  var idx = typeof MISSION_INDEX === 'object' ? MISSION_INDEX : {};
  return idx.hasOwnProperty(url) ? idx[url] : null;
}

// What the app needs to open a day's mission, or null (no mission for that topic, or missions are off for the kid).
function missionView(kid, a, on) {
  if (!a || !on) return null;
  var m = missionOf(a.url);
  return m ? { id: m.id, n: m.n } : null;
}

// One finished mission. The app measures the score; the server checks that it fits the day's mission.
// missed / right: question ids (x:<mission>:<n>) for the spaced review. seconds: time spent playing.
function apiMissionResult(name, pin, date, missionId, correct, total, missed, right, seconds) {
  var kid = auth(name, pin);
  var t = today();
  if (pendingLevelTest(kid)) throw new Error('Take the level test first.');
  if (!missionsOn(kid)) throw new Error('Your daily task is on test-english.com.');
  if (weekDates(t).indexOf(date) < 0 || date > t || date < kidStart(kid)) throw new Error('You can only log tasks from this week.');
  var a = ensureAssignments(kid, [date])[date];
  var m = a && missionOf(a.url);
  if (!m || m.id !== String(missionId)) throw new Error('This mission is not the one for that day. Refresh and try again.');
  correct = Math.round(Number(correct));
  total = Math.round(Number(total));
  seconds = Math.round(Number(seconds)) || 0;
  if (!(total === m.n && correct >= 0 && correct <= total)) throw new Error('Invalid score');
  if (seconds < MISSION.minSeconds) throw new Error('That was too quick to count. Play the mission to the end.');
  var prefix = 'x:' + m.id + ':';
  var mine = function (id) { return id.indexOf(prefix) === 0; };
  missed = cleanIds(missed, total).filter(mine);
  right = cleanIds(right, total).filter(mine);
  var entry;
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    var done = readTableUncached('Log').filter(function (l) { return l.Girl === kid.Name && l.Date === date; });
    if (done.length) throw new Error('This task is already marked as done.');
    var pct = Math.round(correct / total * 100);
    var points = 10 + (pct >= 80 ? 5 : 0) + (date === t ? 3 : 0);
    entry = {
      Timestamp: new Date(), Girl: kid.Name, Date: date, DoneOn: t, Section: a.section, Level: a.level, Title: a.title, URL: a.url,
      Correct: correct, Total: total, Percent: pct, Points: points, Mission: m.id, Seconds: Math.min(seconds, 3600)
    };
    appendRow('Log', entry);
    updateReview(kid.Name, missed, right, t);
  } finally {
    lock.releaseLock();
  }
  try { notifyCompletion(kid, entry); } catch (e) { console.error(e); }
  try { duoAfterPractice(kid.Name); } catch (e) { console.error(e); }
  var dash = buildDashboard(findGirl(kid.Name));
  dash.justEarned = dash.week.filter(function (d) { return d.date === date; })[0].points;
  return dash;
}

// "Something wrong here?" under a question: kept in the Flags tab for the owner to check.
function apiFlag(name, pin, missionId, itemId, note) {
  var kid = auth(name, pin);
  var t = today();
  missionId = String(missionId || '').replace(/[^A-Za-z0-9]/g, '').slice(0, 12);
  itemId = cleanIds([itemId], 1)[0] || '';
  note = String(note || '').replace(/[<>]/g, '').replace(/\s+/g, ' ').trim().slice(0, 300);
  if (!missionId) throw new Error('Unknown mission');
  var mine = readTable('Flags').filter(function (f) { return f.Girl === kid.Name && f.Date === t; });
  if (mine.length >= MISSION.flagsPerDay) return { ok: true };
  appendRow('Flags', { Timestamp: new Date(), Girl: kid.Name, Date: t, Mission: missionId, Item: itemId, Note: note });
  return { ok: true };
}

// ---- src/Pilot.js ----
// The friends' pilot (specs/pilot.md): families join on their own from the owner's invite link, kids find their level
// in the app, parents send feedback, the teacher reviews missions, and the admin sees a funnel per family.

var PILOT = { joinsPerDay: 15, maxKids: 5, feedbackPerDay: 5, teacherFlagsPerDay: 200 };
// The grade a parent picks sets the level the in-app level test starts from.
var GRADE_LEVEL = { 3: 'a1', 4: 'a1', 5: 'a2', 6: 'a2', 7: 'b1', 8: 'b1', 9: 'b1-b2', 10: 'b1-b2', 11: 'b2', 12: 'b2' };

function inviteOk(code) {
  var want = String(getSetting('InviteCode') || '').trim().toLowerCase();
  return !!want && String(getSetting('InviteOpen') || '').trim().toLowerCase() === 'yes' && String(code || '').trim().toLowerCase() === want;
}

// The join screen asks this first, so a closed or wrong link says so before the parent types anything.
function apiJoinCheck(code) {
  ensureSetup();
  var ok = inviteOk(code);
  if (!ok) auditInviteRefused(code);
  return { ok: ok };
}

// data: { family, parent, parentPin, email, consent, kids: [{ name, grade }] }
function apiJoin(code, data) {
  ensureSetup();
  if (!inviteOk(code)) throw new Error('הקישור הזה כבר לא פעיל. בקשו קישור חדש ממי ששלח לכם.');
  data = data || {};
  var clean = function (s, max) { return String(s || '').replace(/[<>"]/g, '').replace(/\s+/g, ' ').trim().slice(0, max); };
  var family = clean(data.family, 40), parentName = clean(data.parent, 40), email = clean(data.email, 80);
  var parentPin = String(data.parentPin || '').trim();
  if (!family) throw new Error('כתבו שם משפחה');
  if (!parentName) throw new Error('כתבו את השם שלכם');
  if (!/^\d{4}$/.test(parentPin)) throw new Error('קוד ההורה צריך להיות 4 ספרות');
  if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) throw new Error('כתובת המייל לא נראית תקינה');
  if (data.consent !== true) throw new Error('צריך לאשר את תנאי הפרטיות כדי להמשיך');
  // A school kid sends a grade (3 to 12); a Coco's Nest kid (Nest.js) sends her age (2 to 7) instead.
  var kids = (data.kids || []).map(function (k) { return { name: clean(k.name, 20), grade: Number(k.grade) || 0, age: Number(k.age) || 0 }; }).filter(function (k) { return k.name; });
  if (!kids.length) throw new Error('הוסיפו לפחות ילד אחד');
  if (kids.length > PILOT.maxKids) throw new Error('אפשר עד ' + PILOT.maxKids + ' ילדים במשפחה');
  kids.forEach(function (k) {
    k.nest = k.age >= NEST.ages[0] && k.age <= NEST.ages[1];
    if (!k.nest && !GRADE_LEVEL[k.grade]) throw new Error('בחרו גיל או כיתה ל' + k.name);
  });

  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  var id, out = [];
  try {
    var gs = readTableUncached('Groups'), t = today();
    if (gs.filter(function (g) { return String(g.Joined || '').slice(0, 10) === t; }).length >= PILOT.joinsPerDay) throw new Error('הגענו למכסת ההרשמות להיום. נסו שוב מחר.');
    if (String(parentPin) === String(getSetting('AdminPIN')) || gs.some(function (g) { return String(g.ParentPIN) === parentPin; })) throw new Error('הקוד הזה תפוס. בחרו 4 ספרות אחרות.');
    var name = family, n = 2;
    while (gs.some(function (g) { return String(g.Name).toLowerCase() === name.toLowerCase(); })) name = family + ' ' + (n++);
    var ids = gs.map(function (g) { return String(g.Id); });
    do { id = Math.random().toString(36).slice(2, 8); } while (ids.indexOf(id) >= 0);
    appendRow('Groups', { Id: id, Name: name, ParentPIN: parentPin, Goal: 1500, GoalReward: 'ערב פיצה משפחתי', Email: email,
      Parent: parentName, Joined: Utilities.formatDate(new Date(), TZ, 'yyyy-MM-dd HH:mm'), Consent: t });
    var girls = readTableUncached('Girls'), taken = girls.map(function (k) { return String(k.Name).toLowerCase(); });
    kids.forEach(function (k, i) {
      // Names are unique across the app: a second Noa becomes "Noa K." (the family's initial), then a number.
      var nm = k.name, initial = family.charAt(0).toUpperCase(), m = 2;
      if (taken.indexOf(nm.toLowerCase()) >= 0) nm = k.name + ' ' + initial + '.';
      while (taken.indexOf(nm.toLowerCase()) >= 0) nm = k.name + ' ' + (m++);
      taken.push(nm.toLowerCase());
      var pin = randomPin();
      appendRow('Girls', { Name: nm, Age: k.nest ? k.age : k.grade + 6, PIN: pin, Level: k.nest ? 'nest' : GRADE_LEVEL[k.grade], Email: '', Redeemed: 0,
        Color: COLORS[(girls.length + i) % COLORS.length], Group: id, Missions: '' });
      out.push({ name: nm, pin: pin, grade: k.grade, age: k.nest ? k.age : null, nest: k.nest });
    });
  } finally {
    lock.releaseLock();
  }
  try { notifyAdmin({ title: 'משפחה חדשה הצטרפה: ' + family, body: parentName + ' · ' + out.map(function (k) { return k.name; }).join(', ') }); } catch (e) { console.error(e); }
  audit('parent', name, id, 'joined', parentName + ' · ' + out.map(function (k) { return k.name; }).join(', '));
  return { groupId: id, family: family, link: groupLink(id), parentPin: parentPin, kids: out };
}

function notifyAdmin(msg) {
  var endpoints = readTable('ParentPush').filter(function (r) { return r.Who === 'admin'; }).map(function (r) { return r.Endpoint; });
  if (endpoints.length) deliver(endpoints, msg, 'ParentPush');
}

// The in-app level test (adaptive blocks from the game bank). form 'A' = the first test, which also logs the level
// like the old link did; form 'B' (or later) = a retest for the before/after report, which does not change the level.
function apiPlacement(name, pin, form, level, correct, total, detail) {
  var kid = auth(name, pin);
  form = String(form || 'A').toUpperCase().slice(0, 1);
  if (LEVELS.indexOf(level) < 0) throw new Error('Unknown level');
  correct = Number(correct) || 0; total = Number(total) || 0;
  if (total < 5 || correct > total) throw new Error('The test is not finished');
  var dash;
  if (form === 'A') {
    var pending = pendingLevelTest(kid);
    if (!pending) throw new Error('Your level is already set.');
    dash = apiSubmit(name, pin, pending.date, correct, total, level);
  }
  var d = {};
  try { d = typeof detail === 'string' ? JSON.parse(detail) : (detail || {}); } catch (e) { d = {}; }
  appendRow('Placements', { Timestamp: new Date(), Girl: kid.Name, Date: today(), Form: form, Start: String(d.start || ''), Level: level,
    Correct: correct, Total: total, Detail: JSON.stringify(d).slice(0, 2000) });
  var out = buildDashboard(findGirl(kid.Name));
  if (dash) out.justEarned = dash.justEarned;
  return out;
}

// A parent's note ("Tell us"): kept in the Feedback tab and pushed to the owner.
function apiFeedback(pin, text, score) {
  ensureSetup();
  var access = parentAccess(pin);
  var who = access.isAdmin ? 'admin' : String(access.group.Id);
  text = String(text || '').replace(/[<>]/g, '').replace(/\s+/g, ' ').trim().slice(0, 1000);
  score = Math.max(0, Math.min(5, Number(score) || 0));
  if (!text && !score) throw new Error('כתבו משהו או בחרו ציון');
  var t = today();
  if (readTable('Feedback').filter(function (f) { return f.Who === who && f.Date === t; }).length >= PILOT.feedbackPerDay) return { ok: true };
  appendRow('Feedback', { Timestamp: new Date(), Who: who, Group: access.isAdmin ? 'admin' : access.group.Name, Date: t, Score: score || '', Text: text });
  if (!access.isAdmin) try { notifyAdmin({ title: 'משוב מ' + access.group.Name + (score ? ' · ' + score + '/5' : ''), body: text.slice(0, 120) }); } catch (e) { console.error(e); }
  return { ok: true };
}

// The teacher plays missions in the preview (?missions&t=<code>) and leaves notes on questions.
function apiTeacherFlag(code, missionId, itemId, note) {
  ensureSetup();
  var want = String(getSetting('TeacherCode') || '').trim();
  checkPin('teacher', !!want && String(code || '').trim() === want);
  missionId = String(missionId || '').replace(/[^A-Za-z0-9]/g, '').slice(0, 12);
  itemId = cleanIds([itemId], 1)[0] || '';
  note = String(note || '').replace(/[<>]/g, '').replace(/\s+/g, ' ').trim().slice(0, 500);
  if (!missionId) throw new Error('Unknown mission');
  var t = today();
  if (readTable('Flags').filter(function (f) { return f.Girl === 'Teacher' && f.Date === t; }).length >= PILOT.teacherFlagsPerDay) return { ok: true };
  appendRow('Flags', { Timestamp: new Date(), Girl: 'Teacher', Date: t, Mission: missionId, Item: itemId, Note: note });
  return { ok: true };
}

function apiTeacherCheck(code) {
  ensureSetup();
  var want = String(getSetting('TeacherCode') || '').trim();
  checkPin('teacher', !!want && String(code || '').trim() === want);
  auditOpen('teacher', 'teacher', '');
  return { ok: true };
}

// The admin's pilot board: per family, where each kid is in the funnel and how active she was.
function apiPilotStats(pin) {
  ensureSetup();
  if (!parentAccess(pin).isAdmin) throw new Error('Only the admin can see this');
  var t = today(), logs = readTable('Log'), games = readTable('Games'), places = readTable('Placements'), fb = readTable('Feedback'), flags = readTable('Flags');
  var active = {};
  logs.forEach(function (l) { (active[l.Girl] = active[l.Girl] || {})[String(l.DoneOn || l.Date)] = true; });
  games.forEach(function (g) { (active[g.Girl] = active[g.Girl] || {})[String(g.Date)] = true; });
  readTable('Chats').forEach(function (r) { (active[r.Girl] = active[r.Girl] || {})[String(r.Date)] = true; });
  // Every group is measured (owner's choice, 2026-10-27): the ones that were in the app before the invite link count
  // from Settings.PilotFrom (set by SETUP v18; change it in the sheet to the opening day).
  var from = String(getSetting('PilotFrom') || t).slice(0, 10);
  var fams = groups().map(function (g) {
    var joined = String(g.Joined || from).slice(0, 10), before = !g.Joined;
    var kids = kidsIn(String(g.Id)).map(function (k) {
      var days = Object.keys(active[k.Name] || {}).filter(function (d) { return d >= joined; }).sort();
      var week = function (w) { var a = addDays(joined, 7 * w), b = addDays(joined, 7 * w + 6); return days.filter(function (d) { return d >= a && d <= b; }).length; };
      var pl = places.filter(function (p) { return p.Girl === k.Name; });
      var missions = logs.filter(function (l) { return l.Girl === k.Name && l.Mission; }).length;
      return { name: k.Name, level: LEVEL_LABEL[k.Level] || k.Level, placed: pl.length > 0 || isNest(k), nest: isNest(k), retest: pl.some(function (p) { return p.Form !== 'A'; }),
        missions: missions, days: days.length, weeks: [week(0), week(1), week(2), week(3)], last: days.length ? days[days.length - 1] : '',
        last7: days.filter(function (d) { return d > addDays(t, -7); }).length };
    });
    return { id: String(g.Id), name: g.Name, parent: g.Parent || '', joined: joined, before: before, day: Math.max(1, daysBetween(joined, t) + 1), kids: kids,
      feedback: fb.filter(function (f) { return f.Who === String(g.Id); }).length };
  });
  var all = [].concat.apply([], fams.map(function (f) { return f.kids; }));
  return {
    families: fams,
    totals: { families: fams.length, kids: all.length, placed: all.filter(function (k) { return k.placed; }).length,
      firstMission: all.filter(function (k) { return k.missions > 0; }).length, active7: all.filter(function (k) { return k.last7 >= 4; }).length },
    feedback: fb.slice(-12).reverse().map(function (f) { return { group: f.Group, date: f.Date, score: f.Score, text: f.Text }; }),
    chat: chatBoard(t),
    teacherFlags: flags.filter(function (f) { return f.Girl === 'Teacher'; }).length,
    teacherCode: String(getSetting('TeacherCode') || ''),
    base: String(getSetting('PublicUrl') || ''),
    invite: { open: String(getSetting('InviteOpen') || '') === 'yes', code: String(getSetting('InviteCode') || '') }
  };
}

// Opens or closes the invite link (and sets its code).
function apiPilotInvite(pin, open, code) {
  ensureSetup();
  if (!parentAccess(pin).isAdmin) throw new Error('Only the admin can change this');
  code = String(code || '').replace(/[^A-Za-z0-9-]/g, '').slice(0, 24);
  if (code) setSetting('InviteCode', code);
  if (!getSetting('InviteCode')) setSetting('InviteCode', Math.random().toString(36).slice(2, 8));
  setSetting('InviteOpen', open ? 'yes' : 'no');
  audit('admin', 'admin', '', 'invite link', (open ? 'opened' : 'closed') + (code ? ', new code' : ''));
  return apiPilotStats(pin);
}

// The kid's in-app level tests for the dashboard: the first level, the retest, and whether the retest is due
// (about four weeks after the first test).
function placementInfo(kid) {
  var rows = readTable('Placements').filter(function (p) { return p.Girl === kid.Name; });
  if (!rows.length) return null;
  var a = rows.filter(function (p) { return p.Form === 'A'; })[0] || rows[0], b = rows.filter(function (p) { return p.Form !== 'A'; }).pop() || null;
  var view = function (p) { return p ? { date: p.Date, level: p.Level, label: LEVEL_LABEL[p.Level] || p.Level, correct: Number(p.Correct), total: Number(p.Total) } : null; };
  return { a: view(a), b: view(b), due: !b && daysBetween(a.Date, today()) >= 25 };
}

// A parent moves a kid to another age or class (the owner, 2026-10-27: a family signed a 5-year-old up as grade 3 before
// Coco's Nest existed). choice = { age: 2..7 } (Coco's Nest) or { grade: 3..12 }. A tested level is kept; a kid with no
// level test (or coming back from the Nest) starts from the class. Days handed out but not played are dropped, so the
// next dashboard builds the new track's day (a pending level test goes away on the way into the Nest).
function apiParentSetAge(pin, name, choice) {
  ensureSetup();
  var access = parentAccess(pin);
  var kid = findGirl(name);
  if (!kid || (!access.isAdmin && groupOf(kid) !== String(access.group.Id))) throw new Error('Unknown kid');
  choice = choice || {};
  var age = Math.round(Number(choice.age)) || 0, grade = Math.round(Number(choice.grade)) || 0;
  var fields, label;
  if (age >= NEST.ages[0] && age <= NEST.ages[1]) {
    fields = { Level: 'nest', Age: age };
    label = "Coco's Nest, age " + age;
  } else if (GRADE_LEVEL[grade]) {
    var tested = readTable('Placements').filter(function (p) { return p.Girl === kid.Name && p.Form === 'A'; })[0];
    fields = { Age: grade + 6 };
    if (!tested) fields.Level = GRADE_LEVEL[grade];
    else if (isNest(kid)) fields.Level = LEVELS.indexOf(String(tested.Level)) >= 0 ? String(tested.Level) : GRADE_LEVEL[grade];
    label = 'grade ' + grade;
  } else {
    throw new Error('בחרו גיל או כיתה');
  }
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    setGirlFields(kid.Name, fields);
    if (isNest(kid) !== (fields.Level === 'nest') && fields.Level !== undefined) dropUnplayedDays(kid.Name);
  } finally {
    lock.releaseLock();
  }
  audit(access.isAdmin ? 'admin' : 'parent', access.isAdmin ? 'admin' : access.group.Name, groupOf(kid), 'kid age', kid.Name + ': ' + label);
  return parentData(access.isAdmin ? groups() : [access.group], access.isAdmin, access.isAdmin ? 'admin' : String(access.group.Id));
}

// Deletes a kid's assignments for days she did not play (a played day keeps its row, so the history stays).
function dropUnplayedDays(name) {
  var played = {};
  readTableUncached('Log').forEach(function (l) { if (l.Girl === name) played[String(l.Date)] = 1; });
  var sh = sheet('Assignments');
  var values = sh.getDataRange().getValues();
  var head = values[0], g = head.indexOf('Girl'), d = head.indexOf('Date');
  for (var i = values.length - 1; i >= 1; i--) {
    var date = values[i][d] instanceof Date ? fmt(values[i][d]) : String(values[i][d]);
    if (String(values[i][g]).trim() === name && !played[date]) sh.deleteRow(i + 1);
  }
  invalidate('Assignments');
}

// ---- src/Chat.js ----
// Talk to Coco (specs/talk.md): short spoken talks with Coco the parrot, scripted in docs/talk/<level>.js on GitHub Pages.
// The phone listens and matches what the kid says to the script; no audio ever leaves the phone. The server keeps a
// summary (how many turns were said aloud, how many with the tiles, and the words the phone heard) and gives a bonus:
// coins and pet XP, never a score. A mission talk (id t<mission>) follows the mission's questions; a home scene
// (id s<level><nn>) is played once a day from the home screen.

var CHAT = { voiceXp: 3, tileXp: 1, allVoice: 3, dayCap: 30, maxTurns: 8, minSeconds: 10, keepIds: 60 };
var CHAT_ID = /^(t(a1|a2|b1|bp|b2|c1)[gvlruw]\d\d|s(a1|a2|b1|bp|b2|c1)\d\d)$/;

// turns: Coco's questions in the talk. voice / tiles: answers said aloud and heard / answered with a tile.
// mic: the phone could listen. said: what the phone heard, one string per answer said aloud.
function apiChatResult(name, pin, id, turns, voice, tiles, mic, said, seconds) {
  var kid = auth(name, pin);
  if (pendingLevelTest(kid)) throw new Error('Take the level test first.');
  id = String(id || '');
  if (!CHAT_ID.test(id)) throw new Error('Unknown talk');
  turns = Math.round(Number(turns));
  voice = Math.round(Number(voice)) || 0;
  tiles = Math.round(Number(tiles)) || 0;
  if (!(turns >= 1 && turns <= CHAT.maxTurns && voice >= 0 && tiles >= 0 && voice + tiles <= turns)) throw new Error('Invalid talk');
  seconds = Math.max(0, Math.min(Math.round(Number(seconds)) || 0, 3600));
  if (seconds < CHAT.minSeconds) throw new Error('That was too quick to count.');
  said = (Array.isArray(said) ? said : []).map(function (s) { return String(s).replace(/[<>|=+@]/g, '').replace(/\s+/g, ' ').trim().slice(0, 160); })
    .filter(Boolean).slice(0, CHAT.maxTurns);
  var where = id.charAt(0) === 't' ? 'mission' : 'home';
  var t = today(), xp;
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    var mine = readTableUncached('Chats').filter(function (r) { return r.Girl === kid.Name && r.Date === t; });
    // The bonus once per talk a day, and once a day for a home scene (a second home talk is practice).
    var again = mine.some(function (r) { return r.Talk === id || (where === 'home' && r.Where === 'home'); });
    var used = mine.reduce(function (a, r) { return a + (Number(r.XP) || 0); }, 0);
    xp = again ? 0 : voice * CHAT.voiceXp + tiles * CHAT.tileXp + (voice === turns ? CHAT.allVoice : 0);
    xp = Math.max(0, Math.min(xp, CHAT.dayCap - used));
    appendRow('Chats', { Timestamp: new Date(), Girl: kid.Name, Date: t, Talk: id, Where: where, Level: kid.Level, Turns: turns, Voice: voice,
      Tiles: tiles, Mic: mic ? 'yes' : 'no', XP: xp, Seconds: seconds, Said: said.join(' | ') });
  } finally {
    lock.releaseLock();
  }
  var dash = buildDashboard(findGirl(kid.Name));
  dash.chatXp = xp;
  return dash;
}

// For the dashboard (and so for the parents): today's home scene, the scenes she has had, this week's talks and the
// longest thing she said aloud this week.
function chatInfo(kid, t) {
  var rows = readTable('Chats').filter(function (r) { return r.Girl === kid.Name; });
  var week = weekDates(t), wk = rows.filter(function (r) { return week.indexOf(String(r.Date)) >= 0; });
  var days = {}, best = '';
  wk.forEach(function (r) {
    if (Number(r.Voice) > 0) days[r.Date] = true;
    String(r.Said || '').split(' | ').forEach(function (s) { if (s && (!best || s.split(' ').length > best.split(' ').length)) best = s; });
  });
  var homes = rows.filter(function (r) { return r.Where === 'home'; }).map(function (r) { return String(r.Talk); });
  return {
    homeToday: rows.some(function (r) { return r.Date === t && r.Where === 'home'; }),
    homeDone: homes.slice(-CHAT.keepIds),
    homeCount: homes.length,
    todayXp: rows.filter(function (r) { return r.Date === t; }).reduce(function (a, r) { return a + (Number(r.XP) || 0); }, 0),
    dayCap: CHAT.dayCap,
    week: wk.length,
    weekVoice: wk.filter(function (r) { return Number(r.Voice) > 0; }).length,
    voiceDays: Object.keys(days).length,
    best: best
  };
}

// The admin's view of stage 0 (does a kid talk aloud?): every kid with a talk, this week and last week.
function chatBoard(t) {
  var rows = readTable('Chats'), ws = weekStart(t), last = addDays(ws, -7), out = {};
  rows.forEach(function (r) {
    var k = out[r.Girl] = out[r.Girl] || { name: r.Girl, talks: 0, voice: 0, tiles: 0, turns: 0, days: {}, lastDays: {}, mic: 0, last: '', said: '' };
    var d = String(r.Date);
    k.talks++;
    k.voice += Number(r.Voice) || 0;
    k.tiles += Number(r.Tiles) || 0;
    k.turns += Number(r.Turns) || 0;
    if (r.Mic === 'yes') k.mic++;
    if (Number(r.Voice) > 0 && d >= ws) k.days[d] = true;
    if (Number(r.Voice) > 0 && d >= last && d < ws) k.lastDays[d] = true;
    if (d >= k.last) { k.last = d; if (r.Said) k.said = String(r.Said).split(' | ').pop(); }
  });
  return Object.keys(out).map(function (n) {
    var k = out[n];
    return { name: k.name, talks: k.talks, voicePct: k.turns ? Math.round(k.voice / k.turns * 100) : 0, tilePct: k.turns ? Math.round(k.tiles / k.turns * 100) : 0,
      micPct: Math.round(k.mic / k.talks * 100), week: Object.keys(k.days).length, lastWeek: Object.keys(k.lastDays).length, last: k.last, said: k.said };
  }).sort(function (a, b) { return b.week - a.week || b.talks - a.talks; });
}

// ---- src/Audit.js ----
// The audit trail (tab Audit, specs/audit.md): who came in, wrong PINs and codes, and what parents, the admin, the
// teacher and the owner (by hand in the sheet) changed. Kids' practice already has its own tabs (Log, Games, Chats...);
// apiAudit merges them with this tab into one timeline for the admin's Audit card.
// An open counts once per half hour per person and device, so a refresh or a return to home is not a new visit.

var AUDIT = { openGapSec: 1800, maxDays: 30, max: 600 };
// The phone's coarse label, sent by the app with every call ("iPhone, app"); set by doPost for this request.
var REQ_DEV = '';

function cleanDev(dev) {
  dev = String(dev || '');
  return /^(iPhone|iPad|Android phone|Android tablet|Computer), (app|browser)$/.test(dev) ? dev : '';
}

// Never breaks the call it records.
function audit(role, who, group, action, detail, ok) {
  try {
    appendRow('Audit', { Timestamp: new Date(), Date: today(), Role: role, Who: String(who || ''), Group: String(group || ''), Action: action,
      Detail: String(detail == null ? '' : detail).slice(0, 200), Ok: ok === false ? 'no' : 'yes', Device: REQ_DEV });
  } catch (e) { console.error(e); }
}

// The detail is how long this phone's previous open took to show its first screen ("1.4s saved", "20s wait" = still
// waiting after 20 s), sent by the app (specs/perf-phase2.md). An open is not written to the sheet during the call (a
// sheet write costs the kid most of a second): it waits in the cache, and auditFlush writes the waiting rows (the
// warmCache trigger every 10 minutes, and before the admin reads the trail).
function auditOpen(role, who, group) {
  var k = 'AO:' + role + ':' + String(who).toLowerCase() + ':' + REQ_DEV;
  var row = { Timestamp: new Date().toISOString(), Date: today(), Role: role, Who: String(who || ''), Group: String(group || ''), Action: 'open',
    Detail: REQ_OPEN ? 'last open ' + REQ_OPEN : '', Ok: 'yes', Device: REQ_DEV };
  var lock = LockService.getScriptLock();
  try {
    var c = CacheService.getScriptCache();
    if (c.get(k)) return;
    c.put(k, '1', AUDIT.openGapSec);
    if (lock.tryLock(1500)) {
      try {
        var q = JSON.parse(c.get('AQ') || '[]');
        if (q.length < 300) { q.push(row); c.put('AQ', JSON.stringify(q), 21600); return; }
      } finally { lock.releaseLock(); }
    }
  } catch (e) {}
  audit(role, who, group, 'open', row.Detail);
}

// Writes the opens waiting in the cache to the Audit tab, in one write.
function auditFlush() {
  var lock = LockService.getScriptLock(), q;
  try {
    if (!lock.tryLock(5000)) return;
    try {
      var c = CacheService.getScriptCache();
      q = JSON.parse(c.get('AQ') || '[]');
      if (!q.length) return;
      c.remove('AQ');
    } finally { lock.releaseLock(); }
    var sh = sheet('Audit'), head = sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0];
    sh.getRange(sh.getLastRow() + 1, 1, q.length, head.length).setValues(q.map(function (r) {
      return head.map(function (h) { return h === 'Timestamp' ? new Date(r.Timestamp) : r[h] === undefined ? '' : r[h]; });
    }));
    invalidate('Audit');
  } catch (e) { console.error(e); }
}

// The app's measure of its last open: seconds to the first screen and where it came from.
var REQ_OPEN = '';
function cleanOpen(s) {
  s = String(s || '');
  return /^\d{1,3}(\.\d)?s (saved|server|offline|wait)$/.test(s) ? s : '';
}

// How long the server takes (specs/perf-phase2.md): the last 40 times of each call, and of apiDashboard's parts, in the
// cache (no sheet). The admin's Audit card shows the median and the slowest. apiDuelPoll is left out (every 2 s in a duel).
var PERF_KEEP = 40;
function perfNote(fn, ms, parts) {
  if (fn === 'apiDuelPoll') return;
  try {
    var c = CacheService.getScriptCache(), p = JSON.parse(c.get('PERF') || '{}');
    var add = function (k, v) { (p[k] = p[k] || []).push(Math.round(v)); if (p[k].length > PERF_KEEP) p[k].shift(); };
    add(fn, ms);
    if (parts) Object.keys(parts).forEach(function (k) { add(fn + '.' + k, parts[k]); });
    c.put('PERF', JSON.stringify(p), 21600);
  } catch (e) {}
}
function perfSummary() {
  var p = {};
  try { p = JSON.parse(CacheService.getScriptCache().get('PERF') || '{}'); } catch (e) {}
  return Object.keys(p).sort().map(function (k) {
    var a = p[k].slice().sort(function (x, y) { return x - y; });
    return { fn: k, n: a.length, median: a[Math.floor(a.length / 2)], max: a[a.length - 1] };
  });
}
var PERF_PARTS = null;

// A wrong PIN or code (checkPin keys: 'girl:<name>', 'parent', 'teacher').
function auditPin(key, fails) {
  var detail = fails >= 8 ? 'locked for 15 minutes' : 'attempt ' + fails;
  if (key.indexOf('girl:') === 0) {
    var kid = findGirl(key.slice(5));
    return audit('kid', kid ? kid.Name : key.slice(5), kid ? groupOf(kid) : '', kid ? 'wrong PIN' : 'unknown name', detail, false);
  }
  audit(key, '', '', key === 'teacher' ? 'wrong code' : 'wrong PIN', detail, false);
}

// A join screen opened from a closed or wrong invite link (once an hour per code, so a reload adds nothing).
function auditInviteRefused(code) {
  try {
    var c = CacheService.getScriptCache(), k = 'AI:' + String(code || '').slice(0, 24).toLowerCase();
    if (c.get(k)) return;
    c.put(k, '1', 3600);
  } catch (e) {}
  var closed = String(getSetting('InviteOpen') || '').trim().toLowerCase() !== 'yes';
  audit('join', '', '', 'invite refused', closed ? 'the link is closed' : 'wrong code', false);
}

// Called by onEdit: a change the owner made by hand in the sheet.
function auditSheetEdit(e) {
  try {
    var sh = e && e.range && e.range.getSheet();
    if (!sh || sh.getName() === 'Audit') return;
    var detail = sh.getName() + '!' + e.range.getA1Notation();
    if (e.range.getNumRows() === 1 && e.range.getNumColumns() === 1) {
      var head = String(sh.getRange(1, e.range.getColumn()).getValue() || '');
      // PINs and codes are never copied into the trail.
      var secret = /PIN|Code/i.test(head) || /PIN|Code/i.test(String(sh.getRange(e.range.getRow(), 1).getValue() || ''));
      detail += ' (' + head + ')' + (secret || e.value === undefined ? '' : ' = ' + String(e.value).slice(0, 60));
    }
    audit('owner', 'sheet', '', 'sheet edit', detail);
  } catch (err) { console.error(err); }
}

// The admin's Audit card: the last `days` days (1 to 30), newest first, and a summary per family.
function apiAudit(pin, days) {
  ensureSetup();
  if (!parentAccess(pin).isAdmin) throw new Error('Only the admin can see this');
  auditFlush();
  days =Math.max(1, Math.min(AUDIT.maxDays, Number(days) || 7));
  var t = today(), from = addDays(t, 1 - days);
  var kids = {}, gname = {};
  readTable('Girls').forEach(function (k) { kids[k.Name] = groupOf(k); });
  groups().forEach(function (g) { gname[String(g.Id)] = g.Name; });
  var inRange = function (r) { var d = String(r.Date || '').slice(0, 10); return d >= from && d <= t; };
  var at = function (r, v) {
    var d = v instanceof Date ? v : new Date(v);
    return isNaN(d.getTime()) ? new Date(String(r.Date).slice(0, 10) + 'T12:00:00').getTime() : d.getTime();
  };
  var ev = [];
  var push = function (r, e) { e.at = at(r, r.Timestamp || r.Created); e.date = String(r.DoneOn || r.Date).slice(0, 10); ev.push(e); };
  var kid = function (r, action, detail) {
    push(r, { role: 'kid', who: r.Girl, group: kids[r.Girl] || '', action: action, detail: detail, ok: true, device: '', practice: true });
  };
  var score = function (r) { return r.Total ? r.Correct + '/' + r.Total : ''; };

  readTable('Audit').filter(inRange).forEach(function (r) {
    push(r, { role: r.Role, who: r.Who, group: r.Group, action: r.Action, detail: r.Detail, ok: r.Ok !== 'no', device: r.Device || '' });
  });
  readTable('Log').filter(inRange).forEach(function (r) {
    kid(r, r.Section === 'level' ? 'level (old link)' : r.Mission ? 'mission' : 'task', [r.Mission || r.Title, score(r), r.Points ? r.Points + ' points' : ''].filter(String).join(' · '));
  });
  readTable('Games').filter(inRange).forEach(function (r) { kid(r, 'game', [r.Game, r.Level, score(r)].filter(String).join(' · ')); });
  readTable('Gates').filter(inRange).forEach(function (r) { kid(r, 'gate', r.From + ' to ' + r.To + ' · ' + score(r) + (r.Passed === 'yes' || r.Passed === true ? ' · passed' : '')); });
  readTable('Chats').filter(inRange).forEach(function (r) { kid(r, 'talk with Coco', r.Talk + ' · ' + r.Voice + ' aloud, ' + r.Tiles + ' tapped'); });
  readTable('Shop').filter(inRange).forEach(function (r) { kid(r, 'bought', r.Item + (r.Paid ? ' · ' + r.Paid + ' coins' : '')); });
  readTable('Placements').filter(inRange).forEach(function (r) { kid(r, 'level test', 'form ' + r.Form + ' · ' + r.Level + ' · ' + score(r)); });
  readTable('Flags').filter(inRange).forEach(function (r) {
    if (r.Girl === 'Teacher') push(r, { role: 'teacher', who: 'teacher', group: '', action: 'flag', detail: r.Mission + ' ' + r.Item, ok: true, device: '' });
    else kid(r, 'flag', r.Mission + ' ' + r.Item);
  });
  readTable('Feedback').filter(inRange).forEach(function (r) {
    push(r, { role: r.Who === 'admin' ? 'admin' : 'parent', who: r.Group, group: r.Who === 'admin' ? '' : r.Who, action: 'feedback',
      detail: (r.Score ? r.Score + '/5 · ' : '') + String(r.Text || '').slice(0, 80), ok: true, device: '' });
  });
  readTable('Duels').filter(inRange).forEach(function (r) {
    push(r, { role: 'kid', who: r.Host, group: kids[r.Host] || '', action: r.Mode === 'boss' ? 'boss battle' : r.Mode === 'talk' ? 'talk & tap' : 'duel',
      detail: (r.Guest ? 'with ' + r.Guest + ' · ' : '') + r.State, ok: true, device: '', practice: true });
  });
  ev.sort(function (a, b) { return a.date === b.date ? b.at - a.at : a.date < b.date ? 1 : -1; });

  // Per family: visits (opens) of kids and of the parent, the last time someone came in, and the devices seen.
  var fams = {};
  groups().forEach(function (g) { fams[String(g.Id)] = { id: String(g.Id), name: g.Name, kidOpens: 0, parentOpens: 0, wrong: 0, last: 0, active: {}, devices: {} }; });
  var devices = {};
  ev.forEach(function (e) {
    var f = fams[e.group];
    if (e.device && e.role !== 'join') devices[e.device + '|' + e.role + '|' + e.who] = e.device;
    if (!f) return;
    if (e.action === 'open') { if (e.role === 'kid') f.kidOpens++; else f.parentOpens++; }
    if (!e.ok) f.wrong++;
    if (e.ok && e.role !== 'owner') f.last = Math.max(f.last, e.at);
    if (e.role === 'kid' && e.ok) f.active[e.who + '|' + e.date] = 1;
    if (e.device) f.devices[e.device] = 1;
  });
  var split = {};
  Object.keys(devices).forEach(function (k) { split[devices[k]] = (split[devices[k]] || 0) + 1; });
  return {
    days: days, from: from, today: t, perf: perfSummary(),
    events: ev.slice(0, AUDIT.max).map(function (e) { e.family = gname[e.group] || ''; return e; }),
    more: Math.max(0, ev.length - AUDIT.max),
    families: Object.keys(fams).map(function (id) {
      var f = fams[id];
      return { id: id, name: f.name, kidOpens: f.kidOpens, parentOpens: f.parentOpens, wrong: f.wrong, last: f.last || null,
        kidDays: Object.keys(f.active).length, devices: Object.keys(f.devices) };
    }).sort(function (a, b) { return (b.last || 0) - (a.last || 0); }),
    devices: split
  };
}

// ---- src/Nest.js ----
// Coco's Nest (specs/nest.md): the track for ages 2 to 7. A Nest kid has Level 'nest' (outside LEVELS, so the level chain,
// journeys, gates and the catalog never see her) and her real age. One day a day in the order of NEST_UNITS
// (src/NestIndex.js, written by tools/nest-index.js from docs/nest/nest.js): a unit is four days (n04 new words,
// n04.b move, n04.c song and story, n04.d games) and a review is one (r02). No level test, no link out.

var NEST = { points: 15, latePoints: 12, minTotal: 1, maxTotal: 40, maxSeconds: 3600, ages: [2, 7], detailMax: 800 };
var NEST_DAY = /^[nr]\d\d(\.[bcd])?$/, NEST_DETAIL = /^[a-z0-9-]+:[01](,[a-z0-9-]+:[01])*$/;

function isNest(kid) { return !!kid && String(kid.Level || '').trim().toLowerCase() === 'nest'; }

function nestUnits() { return typeof NEST_UNITS === 'object' && NEST_UNITS.length ? NEST_UNITS : [['n01', 'Hello, Coco!', 0]]; }

// The day for a date: the first one she has not played yet, then around again. It follows what she played, not the
// calendar, so a missed day (or a move into the Nest in the middle of a week) never skips a unit.
function nestNext(kid, logs) {
  var units = nestUnits(), played = {}, n = 0;
  (logs || readTable('Log')).forEach(function (l) { if (l.Girl === kid.Name && l.Section === 'nest' && l.Mission) { played[l.Mission] = 1; n++; } });
  for (var i = 0; i < units.length; i++) if (!played[units[i][0]]) return nestAssignment(units[i]);
  return nestAssignment(units[n % units.length]);
}

function nestAssignment(u) { return { section: 'nest', level: 'nest', title: u[1], url: 'nest:' + u[0] }; }

function nestAge(kid) {
  var a = Math.round(Number(kid.Age));
  return a >= NEST.ages[0] && a <= NEST.ages[1] ? a : 5;
}

// What the Nest home needs: the age (how many pictures, whether words are shown), today's day, the days played, and
// per word [days found on the first try, days missed, the last day met] for the review days.
function nestInfo(kid, t, assigned, logs) {
  var a = assigned[t], played = [], seen = {}, words = {};
  logs.forEach(function (l) {
    if (l.Section !== 'nest') return;
    if (l.Mission && !seen[l.Mission]) { seen[l.Mission] = 1; played.push(String(l.Mission)); }
    String(l.Detail || '').split(',').forEach(function (x) {
      var p = x.split(':');
      if (!p[0] || (p[1] !== '0' && p[1] !== '1')) return;
      var w = words[p[0]] = words[p[0]] || [0, 0, ''];
      w[p[1] === '1' ? 0 : 1]++;
      if (String(l.Date) > w[2]) w[2] = String(l.Date);
    });
  });
  var age = nestAge(kid), done = logs.some(function (l) { return l.Date === t; }), perDay = nestPerDay(kid);
  var today = logs.filter(function (l) { return l.Date === t && l.Section === 'nest'; }).length;
  return {
    age: age, choices: age <= 4 ? 2 : 3, words: age >= 6,
    today: a && a.section === 'nest' ? String(a.url).slice(5) : null,
    done: done,
    played: played,
    known: words,
    all: nestAllOpen(kid),
    // The living home (specs/nest-home.md) and the arcade (a live Coco, real sounds, the band, Coco's games): every Nest kid
    // since 2026-10-29 (the owner). Settings.NestHome / NestArcade = 'off' closes one again for everyone.
    home: !nestOff('NestHome'),
    arcade: !nestOff('NestArcade'),
    // Days played (distinct dates with a Nest row): a flower each in the home's garden.
    days: logs.filter(function (l) { return l.Section === 'nest'; }).map(function (l) { return String(l.Date); }).filter(function (d, i, a) { return a.indexOf(d) === i; }).length,
    perDay: perDay,
    // Minutes a day in Coco's arcade (the parent sets it; 0 = no limit). The phone counts the minutes.
    arcadeMin: nestArcadeMin(kid),
    // One more lesson: once the day's own is done, the next day of the program while the parent's daily number allows.
    next: done && (!perDay || today < perDay) ? String(nestNext(kid, logs).url).slice(5) : null
  };
}

// Lessons a day (Girls.NestPerDay, set by the parent): 1 when empty, 0 = no limit.
function nestPerDay(kid) {
  var v = String(kid.NestPerDay == null ? '' : kid.NestPerDay).trim();
  if (v === '') return 1;
  var n = Math.round(Number(v));
  return n >= 0 && n <= 9 ? n : 1;
}

function apiParentNestPerDay(pin, name, n) {
  ensureSetup();
  var access = parentAccess(pin);
  var kid = findGirl(name);
  if (!kid || !isNest(kid) || (!access.isAdmin && groupOf(kid) !== String(access.group.Id))) throw new Error('Unknown kid');
  n = Math.round(Number(n));
  if (!(n >= 0 && n <= 9)) throw new Error('בחרו כמה שיעורים ביום');
  setGirlFields(kid.Name, { NestPerDay: n });
  audit(access.isAdmin ? 'admin' : 'parent', access.isAdmin ? 'admin' : access.group.Name, groupOf(kid), 'nest lessons a day', kid.Name + ': ' + (n || 'no limit'));
  return parentData(access.isAdmin ? groups() : [access.group], access.isAdmin, access.isAdmin ? 'admin' : String(access.group.Id));
}

// Minutes a day in Coco's arcade (Girls.NestArcadeMin, set by the parent): 15 when empty, 0 = no limit.
function nestArcadeMin(kid) {
  var v = String(kid.NestArcadeMin == null ? '' : kid.NestArcadeMin).trim();
  if (v === '') return 15;
  var n = Math.round(Number(v));
  return n >= 0 && n <= 60 ? n : 15;
}

function apiParentNestArcade(pin, name, n) {
  ensureSetup();
  var access = parentAccess(pin);
  var kid = findGirl(name);
  if (!kid || !isNest(kid) || (!access.isAdmin && groupOf(kid) !== String(access.group.Id))) throw new Error('Unknown kid');
  n = Math.round(Number(n));
  if (!(n >= 0 && n <= 60)) throw new Error('בחרו כמה דקות ביום');
  setGirlFields(kid.Name, { NestArcadeMin: n });
  audit(access.isAdmin ? 'admin' : 'parent', access.isAdmin ? 'admin' : access.group.Name, groupOf(kid), 'nest arcade minutes', kid.Name + ': ' + (n || 'no limit'));
  return parentData(access.isAdmin ? groups() : [access.group], access.isAdmin, access.isAdmin ? 'admin' : String(access.group.Id));
}

// Settings.NestAll: the names (comma separated, or 'all') whose Nest home shows every unit and day now, as free play.
// A try-out switch for the owner; the day's own session still comes one a day.
function nestAllOpen(kid) { return nestNamesOpen('NestAll', kid); }
function nestOff(setting) { return String(getSetting(setting) || '').trim().toLowerCase() === 'off'; }
function nestNamesOpen(setting, kid) {
  var v = String(getSetting(setting) || '').toLowerCase().split(',').map(function (s) { return s.trim(); });
  return v.indexOf('all') >= 0 || v.indexOf(String(kid.Name || '').toLowerCase()) >= 0;
}

function apiAdminNestAll(pin, names) {
  ensureSetup();
  if (!parentAccess(pin).isAdmin) throw new Error('Only the admin can change settings');
  names = String(names || '').split(',').map(function (s) { return s.trim(); }).filter(String).join(',');
  setSetting('NestAll', names);
  audit('admin', 'admin', '', 'nest all open', names || 'none');
  return { ok: true, names: names };
}

// One finished session. The day's own session logs the day (points whatever the score: no pressure at this age); any
// other day, or the same one again, is free play and changes nothing. detail: each word's first try ("cat:1,dog:0").
function apiNestResult(name, pin, date, unitId, correct, total, seconds, detail) {
  var kid = auth(name, pin);
  if (!isNest(kid)) throw new Error('Unknown activity');
  var t = today();
  unitId = String(unitId || '');
  if (!NEST_DAY.test(unitId)) throw new Error('Unknown activity');
  detail = String(detail || '');
  if (detail.length > NEST.detailMax || (detail && !NEST_DETAIL.test(detail))) detail = '';
  correct = Math.round(Number(correct));
  total = Math.round(Number(total));
  if (!(total >= NEST.minTotal && total <= NEST.maxTotal && correct >= 0 && correct <= total)) throw new Error('Invalid score');
  seconds = Math.max(0, Math.min(NEST.maxSeconds, Math.round(Number(seconds)) || 0));
  var free = function () { var d = buildDashboard(findGirl(kid.Name)); d.justEarned = 0; d.free = true; return d; };
  if (weekDates(t).indexOf(date) < 0 || date > t || date < kidStart(kid)) return free();
  var a = ensureAssignments(kid, [date])[date];
  if (!a) return free();
  var entry = null;
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    var mine = readTableUncached('Log').filter(function (l) { return l.Girl === kid.Name; });
    if (a.url !== 'nest:' + unitId) {
      // One more lesson today: the day's own is logged, this is the next day of the program, and the parent allows it.
      var perDay = nestPerDay(kid), todays = mine.filter(function (l) { return l.Date === t && l.Section === 'nest'; }).length;
      var next = nestNext(kid, mine);
      if (date !== t || !todays || (perDay && todays >= perDay) || next.url !== 'nest:' + unitId) return free();
      a = next;
    } else if (mine.some(function (l) { return l.Date === date; })) return free();
    entry = {
      Timestamp: new Date(), Girl: kid.Name, Date: date, DoneOn: t, Section: 'nest', Level: 'nest', Title: a.title, URL: a.url,
      Correct: correct, Total: total, Percent: Math.round(correct / total * 100), Points: date === t ? NEST.points : NEST.latePoints,
      Mission: unitId, Seconds: seconds, Detail: detail
    };
    appendRow('Log', entry);
  } finally {
    lock.releaseLock();
  }
  try { notifyCompletion(kid, entry); } catch (e) { console.error(e); }
  var dash = buildDashboard(findGirl(kid.Name));
  dash.justEarned = entry.Points;
  return dash;
}

